-- 병원 소개글(description)·영업시간(business_hours) 다국어화(EN/ZH/JA).
-- name/address는 번역 대상에서 제외(고유명사·실주소는 원문 유지가 실사용에 유리).
-- description_en/zh/ja, business_hours_en/zh/ja는 db/seed/hospitals.json(다국어화 완료본) 기준으로
-- 생성한 UPDATE문이다. business_hours 원본 컬럼은 business_hours_ko로 이름만 바꾸고 값은 그대로 둔다.

ALTER TABLE hospital CHANGE COLUMN business_hours business_hours_ko TEXT;
ALTER TABLE hospital ADD COLUMN business_hours_en TEXT;
ALTER TABLE hospital ADD COLUMN business_hours_zh TEXT;
ALTER TABLE hospital ADD COLUMN business_hours_ja TEXT;
ALTER TABLE hospital ADD COLUMN description_zh TEXT;
ALTER TABLE hospital ADD COLUMN description_ja TEXT;

UPDATE hospital SET description_en = 'We help every child grow up healthy and strong. General care and student check-ups are on the 2nd floor, and the Growth Clinic is on the 9th floor. Pediatric specialist care and vaccinations are available on Saturdays, Sundays, and public holidays, along with adult care/IV treatment. Call 051-711-7878 to book the Growth/Precocious Puberty Clinic (weekdays 10:00-18:00); use Naver Reservation for student and infant check-ups.', description_zh = '帮助每一位孩子健康成长。普通诊疗·学生体检在2楼，生长门诊在9楼进行。周六、周日、法定假日均可接受儿科专科医生诊疗及疫苗接种，并可提供成人诊疗/输液治疗。生长·性早熟门诊电话预约051-711-7878（工作日10:00~18:00），学生体检·婴幼儿体检请使用Naver预约。', description_ja = 'すべての子どもの健やかな成長をサポートします。一般診療・学生検診は2階、成長クリニックは9階で行います。土・日・祝日も小児科専門医の診療および予防接種、成人診療/輸液治療が可能です。成長・性早熟クリニックの電話予約は051-711-7878（平日10時~18時）、学生検診・乳幼児検診はNAVER予約をご利用ください。', business_hours_en = 'Mon 09:00-18:30 / Tue 09:00-18:30 / Wed 09:00-18:30 / Thu 09:00-18:30 / Fri 09:00-18:30 / Sat 09:00-15:00 / Closed Sun (weekday lunch break 13:00-14:00, Saturday 13:00-13:30, closed every May 1 for Workers'' Day)', business_hours_zh = '周一 09:00-18:30 / 周二 09:00-18:30 / 周三 09:00-18:30 / 周四 09:00-18:30 / 周五 09:00-18:30 / 周六 09:00-15:00 / 周日休诊（工作日午休13:00-14:00，周六13:00-13:30，每年5月1日劳动节休息）', business_hours_ja = '月 09:00-18:30 / 火 09:00-18:30 / 水 09:00-18:30 / 木 09:00-18:30 / 金 09:00-18:30 / 土 09:00-15:00 / 日休診（平日昼休み13:00-14:00、土曜13:00-13:30、毎年5月1日勤労者の日休診）' WHERE reg_no = '1';
UPDATE hospital SET description_en = 'Joint and spine specialty hospital located 200m from Exit 1 of Minam Station. Follows a non-surgical-first treatment principle. Orthopedics, neurosurgery, and internal medicine. Joints (shoulder/knee/robotic artificial joint/foot & ankle/hip/elbow/fracture/ligament tear), spine (non-surgical-first treatment/bi-portal endoscopic surgery/minimally invasive spine surgery), internal medicine (osteoporosis/diabetes/hypertension/hyperlipidemia/health checkups). Rehabilitation center (manual therapy/physical therapy/exercise therapy/shockwave therapy), national health checkup (gastric/colon endoscopy).', description_zh = '位于地铁美男站1号出口（步行200米）的关节·脊柱专科医院。坚持非手术优先治疗原则。设骨科、神经外科、内科。关节（肩/膝/机器人人工关节/足踝/髋/肘/骨折/韧带撕裂）、脊柱（非手术优先治疗/双通道内镜手术/微创脊柱手术）、内科（骨质疏松/糖尿病/高血压/高脂血症/健康体检）。康复治疗中心（徒手治疗/物理治疗/运动治疗/体外冲击波治疗），国家健康体检（胃·大肠内镜）。', description_ja = '地下鉄美男駅1番出口（徒歩200m）にある関節・脊椎専門病院。非手術優先治療を原則としています。整形外科・神経外科・内科診療。関節（肩/膝/ロボット人工関節/足関節/股関節/肘関節/骨折/靭帯断裂）、脊椎（非手術優先治療/両方向内視鏡手術/最小侵襲脊椎手術）、内科（骨粗鬆症/糖尿病/高血圧/高脂血症/健康診断）。リハビリテーションセンター（徒手治療/物理治療/運動治療/体外衝撃波治療）、国家健康診断（胃・大腸内視鏡）。', business_hours_en = 'Mon-Fri 09:00-18:00 (last check-in 17:30) / Sat 09:00-13:00 (last check-in 12:30) / Closed every other Sunday, closed 08/15 Liberation Day (lunch break 13:00-14:00, closed on public holidays)', business_hours_zh = '周一至周五 09:00-18:00（最晚挂号17:30）/ 周六 09:00-13:00（最晚挂号12:30）/ 隔周周日定期休息，8月15日光复节休息（午休13:00-14:00，法定假日休诊）', business_hours_ja = '月~金 09:00-18:00（受付終了17:30）/ 土 09:00-13:00（受付終了12:30）/ 日曜隔週定休、8/15光復節休診（昼休み13:00-14:00、祝日休診）' WHERE reg_no = '2';
UPDATE hospital SET description_en = 'Himnaera Hospital, an orthopedic hospital in Busan, has provided high-quality care to patients with spine and joint conditions since 2015, drawing on ongoing research and published papers to find the right treatment for each patient. Call 051-711-9500 for inquiries.', description_zh = '釜山骨科힘내라（Himnaera）医院自2015年起针对脊柱·关节疾病患者，通过持续的研究和论文寻找适合的治疗方法，提供高质量的医疗服务。电话咨询051-711-9500。', description_ja = '釜山整形外科ヒムネラ病院は、脊椎・関節疾患を抱える患者を対象に2015年から研究と論文を通じて適した治療法を見出し、質の高い医療サービスを提供しています。お電話でのお問い合わせは051-711-9500。', business_hours_en = 'Mon 09:00-18:00 / Tue-Fri 09:00-17:30 (lunch break 12:30-13:30) / Sat 09:00-13:00 / Closed Sun (closed 08/15 Liberation Day)', business_hours_zh = '周一 09:00-18:00 / 周二至周五 09:00-17:30（午休12:30-13:30）/ 周六 09:00-13:00 / 周日休诊（8月15日光复节休息）', business_hours_ja = '月 09:00-18:00 / 火~金 09:00-17:30（昼休み12:30-13:30）/ 土 09:00-13:00 / 日休診（8/15光復節休診）' WHERE reg_no = '3';
UPDATE hospital SET description_en = 'Nell Clinic in Seomyeon — the choice for confident, beautiful skin. We analyze your skin condition and propose a tailored solution. Treatments: stem cell therapy, lifting, fillers, Botox, laser, skin boosters, custom skin clinic, body clinic, hair removal, men''s care. Equipment: Thermage FLX, Ulthera, Repot Laser, InMode, Virtue, Oligio, and more.', description_zh = '自信肌肤，美丽之选——西面皮肤科넬（Nell）医院。分析皮肤状态后提供定制方案。诊疗·项目：干细胞、提升、玻尿酸填充、肉毒素、激光、水光针、定制皮肤门诊、身体门诊、脱毛、男士护理。配备设备：Thermage FLX、Ulthera、Repot激光、InMode、Virtue、Oligio等。', description_ja = '自信の持てる肌、美しさのための選択、ソミョン皮膚科ネルクリニック。肌状態の分析後、オーダーメイドソリューションをご提案。診療・施術科目：幹細胞、リフティング、フィラー、ボトックス、レーザー、スキンブースター、オーダーメイド皮膚クリニック、ボディクリニック、脱毛、メンズケア。保有機器：サーマジFLX、ウルセラ、リポットレーザー、インモード、バーチュ、オリジオなど。', business_hours_en = 'Mon/Wed/Thu 10:00-19:00 / Tue/Fri 10:00-21:00 / Sat 10:00-15:00 (lunch break 13:00-14:00) / Closed Sun (closed 08/15 Liberation Day)', business_hours_zh = '周一·周三·周四 10:00-19:00 / 周二·周五 10:00-21:00 / 周六 10:00-15:00（午休13:00-14:00）/ 周日休诊（8月15日光复节休息）', business_hours_ja = '月・水・木 10:00-19:00 / 火・金 10:00-21:00 / 土 10:00-15:00（昼休み13:00-14:00）/ 日休診（8/15光復節休診）' WHERE reg_no = '4';
UPDATE hospital SET description_en = 'A hairline and hair transplant specialty clinic that always puts the patient''s best interest first. Hairline surgery prioritizes a natural look, and crown hair transplants proceed only after fully checking hair-loss progression and response to medication. Uses the latest equipment such as LDM Triple and Needle RF. The director personally oversees everything from consultation to surgery. Phone consultation: 051-817-7878.', description_zh = '以患者利益为先的发际线·植发专科医院。发际线手术以自然效果为优先，头顶植发则在充分确认脱发进展和药物治疗反应后进行。采用LDM Triple、Needle RF等最新设备。院长亲自负责从咨询到手术的全过程。电话咨询051-817-7878。', description_ja = '患者にとって最も正しいことを第一に考えるヘアライン・毛髪移植専門クリニック。ヘアライン手術は自然な仕上がりを優先し、頭頂部の毛髪移植は脱毛の進行と薬物治療への反応を十分確認した上で行います。LDM Triple、Needle RFなど最新機器を活用。院長がカウンセリングから手術まで直接担当。お電話でのご相談は051-817-7878。', business_hours_en = 'Mon-Fri 10:00-19:00 (lunch break 12:00-13:00, last check-in 18:30) / Sat 09:00-15:00 (last check-in 14:30) / Closed Sun', business_hours_zh = '周一至周五 10:00-19:00（午休12:00-13:00，最晚挂号18:30）/ 周六 09:00-15:00（最晚挂号14:30）/ 周日休诊', business_hours_ja = '月~金 10:00-19:00（昼休み12:00-13:00、受付終了18:30）/ 土 09:00-15:00（受付終了14:30）/ 日休診' WHERE reg_no = '5';
UPDATE hospital SET description_en = 'Offers cataract surgery, LASIK, LASEK, lens implantation, and presbyopia surgery, as well as outpatient care for glaucoma, dry eye, and other eye conditions. Operates an open surgical suite, recommends personalized 1:1 vision correction surgery, and offers same-day exams and same-day surgery.', description_zh = '开展白内障手术、LASIK、LASEK、晶体植入术、老花手术，以及青光眼、干眼症等眼科门诊诊疗。设有开放式手术室，推荐一对一定制视力矫正手术，可当日检查·当日手术。', description_ja = '白内障手術、レーシック、ラゼック、眼内レンズ挿入術、老眼手術のほか、緑内障・ドライアイなど眼科外来診療を実施。オープン手術室を運営し、1対1のオーダーメイド視力矯正手術を推奨、当日検査・当日手術も可能。', business_hours_en = 'Mon-Fri 09:30-17:30 (lunch break 12:30-14:00) / Sat 09:30-12:30 / Closed Sun (closed 08/15 Liberation Day, 08/17 substitute holiday)', business_hours_zh = '周一至周五 09:30-17:30（午休12:30-14:00）/ 周六 09:30-12:30 / 周日休诊（8月15日光复节、8月17日替代假日休息）', business_hours_ja = '月~金 09:30-17:30（昼休み12:30-14:00）/ 土 09:30-12:30 / 日休診（8/15光復節、8/17振替休日休診）' WHERE reg_no = '6';
UPDATE hospital SET description_en = 'Founded in 2000, a 26-year-old ophthalmology clinic specializing in LASIK and LASEK. Offers a lifetime free re-treatment guarantee for myopia regression. Treatments include Smart LASIK, Today LASEK, Dream Lens (Ortho-K), presbyopia correction, and cataract care.', description_zh = '2000年开院，拥有26年历史的LASIK·LASEK专业眼科。提供近视回退终身免费复矫保证。诊疗项目包括Smart LASIK、Today LASEK、梦戴维角膜塑形镜、老花矫正、白内障等。', description_ja = '2000年開院、26年の歴史を持つレーシック・ラゼック専門眼科。近視の戻り（退行）に対する再手術を生涯無料で保証。スマートレーシック・トゥデイラゼック・ドリームレンズ（オルソケラトロジー）・老眼矯正・白内障などを診療。', business_hours_en = 'Mon/Tue/Wed/Fri 10:00-18:00 (lunch break 12:30-14:00, last check-in 17:30) / Closed Thu / Sat 09:00-14:30 (last check-in 14:00) / Closed Sun (closed 08/15 Liberation Day, 08/17 substitute holiday)', business_hours_zh = '周一·周二·周三·周五 10:00-18:00（午休12:30-14:00，最晚挂号17:30）/ 周四休诊 / 周六 09:00-14:30（最晚挂号14:00）/ 周日休诊（8月15日光复节、8月17日替代假日休息）', business_hours_ja = '月・火・水・金 10:00-18:00（昼休み12:30-14:00、受付終了17:30）/ 木休診 / 土 09:00-14:30（受付終了14:00）/ 日休診（8/15光復節、8/17振替休日休診）' WHERE reg_no = '7';
UPDATE hospital SET description_en = 'Specializes in the full range of urology — erectile dysfunction, penile enlargement, glans enlargement, radiofrequency treatment for premature ejaculation, vasectomy/circumcision, benign prostatic hyperplasia — and male body contouring (gynecomastia, liposuction, etc.). All-male staff, air-shower disinfection system. Inquiries: 010-4051-8275 / 051-817-8575.', description_zh = '专注泌尿外科全领域诊疗：勃起功能障碍、阴茎增大术、龟头增大术、高频早泄手术、输精管结扎·包皮环切术、前列腺肥大等，以及男性体形（男性乳房发育症、吸脂等）专项。全体员工均为男性，配备风淋消毒系统。咨询电话010-4051-8275 / 051-817-8575。', description_ja = '勃起不全、陰茎増大術、亀頭増大術、高周波早漏手術、精管・包茎手術、前立腺肥大症など泌尿器科全般および男性体型（女性化乳房、脂肪吸引など）専門。全スタッフ男性、エアシャワー消毒システム完備。お問い合わせ010-4051-8275 / 051-817-8575。', business_hours_en = 'Mon-Fri 09:30-17:30 / Sat 09:30-14:30 / Closed Sun (closed 08/15 Liberation Day, 08/17 substitute holiday; on the 1st/3rd/5th Saturdays only surgical consultations are available)', business_hours_zh = '周一至周五 09:30-17:30 / 周六 09:30-14:30 / 周日休诊（8月15日光复节、8月17日替代假日休息，第1·3·5周周六仅提供手术咨询）', business_hours_ja = '月~金 09:30-17:30 / 土 09:30-14:30 / 日休診（8/15光復節、8/17振替休日休診、第1・3・5土曜は手術相談のみ可）' WHERE reg_no = '8';
UPDATE hospital SET description_en = 'A first-generation ophthalmology clinic founded in 2000. Outpatient care and exams are at the main branch (Seomyeon Station Exit 13), and surgery takes place at the branch clinic (Seomyeon Station Exit 15). Treats cataracts, glaucoma, retinal disease, pediatric eye conditions, and dry eye, and performs LASIK, LASEK, SMILE LASIK, and lens implantation surgery.', description_zh = '2000年开院的第一代眼科。本院（西面站13号出口）负责门诊·检查，分院（西面站15号出口）负责手术。诊疗白内障、青光眼、视网膜疾病、小儿眼科、干眼症等，并开展LASIK、LASEK、SMILE全飞秒、晶体植入术等手术。', description_ja = '2000年開院の第一世代眼科。本院（ソミョン駅13番出口）で外来診療・検査、分院（ソミョン駅15番出口）で手術を実施。白内障、緑内障、網膜疾患、小児眼科、ドライアイなどの診療、およびレーシック・ラゼック・スマイルレーシック・眼内レンズ挿入術などの手術。', business_hours_en = 'Mon-Fri 09:00-18:00 (lunch break 13:00-14:00, last check-in 17:30) / Sat 09:00-13:00 (last check-in 12:30) / Closed Sun', business_hours_zh = '周一至周五 09:00-18:00（午休13:00-14:00，最晚挂号17:30）/ 周六 09:00-13:00（最晚挂号12:30）/ 周日休诊', business_hours_ja = '月~金 09:00-18:00（昼休み13:00-14:00、受付終了17:30）/ 土 09:00-13:00（受付終了12:30）/ 日休診' WHERE reg_no = '9';
UPDATE hospital SET description_en = 'A leading plastic surgery clinic in Busan/Gyeongnam led by a plastic surgeon with 28 years of experience. CCTV in the operating room and exam rooms addresses concerns about ghost surgery. Services include eyes, nose, revision surgery, facial contouring, breast surgery, liposuction, lifting, fillers, and Botox, with free interpretation support in Japanese, Chinese, Vietnamese, Russian, and Thai.', description_zh = '由拥有28年经验的整形外科专科医生领衔，釜山·庆南地区代表性整形外科。手术室·诊室配备CCTV，杜绝“代做手术”隐患。诊疗项目涵盖眼部、鼻部、修复手术、面部轮廓、胸部整形、吸脂、提升、玻尿酸填充、肉毒素等，并提供日语·中文·越南语·俄语·泰语免费翻译服务。', description_ja = '28年のキャリアを持つ美容外科専門医が率いる釜山・慶南を代表する美容外科。手術室・診察室にCCTVを設置し、代理手術の懸念を解消。目・鼻・再手術・顔輪郭・豊胸・脂肪吸引・リフティング・フィラー・ボトックスなどを診療、日本語・中国語・ベトナム語・ロシア語・タイ語の無料通訳サポートあり。', business_hours_en = 'Mon/Tue/Thu 10:00-19:00 (last check-in 18:30) / Wed/Fri 10:00-20:00 (last check-in 19:30) / Sat 10:00-16:00 (last check-in 15:30) / Closed Sun (closed 08/15 Liberation Day)', business_hours_zh = '周一·周二·周四 10:00-19:00（最晚挂号18:30）/ 周三·周五 10:00-20:00（最晚挂号19:30）/ 周六 10:00-16:00（最晚挂号15:30）/ 周日休诊（8月15日光复节休息）', business_hours_ja = '月・火・木 10:00-19:00（受付終了18:30）/ 水・金 10:00-20:00（受付終了19:30）/ 土 10:00-16:00（受付終了15:30）/ 日休診（8/15光復節休診）' WHERE reg_no = '10';
UPDATE hospital SET description_en = 'Located at Seomyeon Station Exit 9. A hospital-grade dental clinic staffed by oral and maxillofacial surgery specialists and a dental anesthesiology PhD. In-house care covers implants (3D CT-based), orthodontics (Invisalign, etc.), double-jaw/facial contouring surgery, sleep dentistry, wisdom tooth extraction, and prosthodontic/conservative treatment. Inpatient rooms support post-surgery recovery. Inquiries: 051-802-6363.', description_zh = '位于西面站9号出口。由口腔颌面外科专科医生、牙科麻醉痛症学博士坐诊的医院级牙科。院内可完成种植牙（基于3D CT）、牙齿矫正（隐适美等）、双颌手术·面部轮廓、睡眠牙科治疗、智齿拔除、修复·保存治疗等全部诊疗项目。设有住院病房支持术后恢复。咨询电话051-802-6363。', description_ja = 'ソミョン駅9番出口に位置。口腔顎顔面外科専門医・歯科麻酔科学博士が診療する病院級歯科。インプラント（3D CTベース）、歯列矯正（インビザラインなど）、両顎手術・顔輪郭、睡眠歯科治療、親知らず抜歯、補綴・保存治療など全診療科目を院内でケア。入院室を運営し術後回復をサポート。ご相談は051-802-6363。', business_hours_en = 'Thu/Fri 09:30-19:00 / Sat 09:30-17:00 / Closed Sun (closed 08/17, 08/23 — please check the website for exact weekday hours)', business_hours_zh = '周四·周五 09:30-19:00 / 周六 09:30-17:00 / 周日休诊（8月17日、8月23日休息——工作日具体诊疗时间请以官网为准）', business_hours_ja = '木・金 09:30-19:00 / 土 09:30-17:00 / 日休診（8/17、8/23休診 — 平日の正確な診療時間は公式サイトでご確認ください）' WHERE reg_no = '11';
UPDATE hospital SET description_en = 'A joint- and spine-focused hospital operating since 2011. University-hospital-trained orthopedic staff provide specialized, tailored care, with added expertise in neurology, internal medicine, and health checkups. Operates caregiver-free wards with 24-hour nursing, and has introduced the MAKO robotic joint replacement system.', description_zh = '自2011年起持续运营的关节·脊柱专科医院。由大学医院出身的骨科医疗团队提供细分定制诊疗，并在神经内科、内科、健康体检方面同样专业。设有24小时护理的无陪护病房，并引进MAKO机器人人工关节手术设备。', description_ja = '2011年から続く関節・脊椎中心の病院。大学病院出身の整形外科医療陣によるきめ細やかなオーダーメイド診療、神経科・内科・健康診断まで特化。24時間看護体制の付き添い不要病棟を運営、ロボット人工関節手術機器MAKO（マコ）を導入。', business_hours_en = 'Mon-Fri 09:00-19:00 (lunch break 12:30-13:30, last check-in 18:30) / Sat 09:00-14:00 (lunch break 12:00-12:30, last check-in 13:30) / Closed Sun (contact separately for internal medicine/neurology schedules)', business_hours_zh = '周一至周五 09:00-19:00（午休12:30-13:30，最晚挂号18:30）/ 周六 09:00-14:00（午休12:00-12:30，最晚挂号13:30）/ 周日休诊（内科·神经内科诊疗时间另行咨询）', business_hours_ja = '月~金 09:00-19:00（昼休み12:30-13:30、受付終了18:30）/ 土 09:00-14:00（昼休み12:00-12:30、受付終了13:30）/ 日休診（内科・神経科の診療スケジュールは別途お問い合わせください）' WHERE reg_no = '12';
UPDATE hospital SET description_en = 'A multi-specialty clinic combining orthopedics, internal medicine, and general surgery. Collaborative care across surgery (varicose veins, hemorrhoids, breast, etc.), internal medicine (gastric/colon endoscopy, health checkups), and orthopedics (non-surgical pain, joint, and spine treatment).', description_zh = '骨科·内科·外科综合诊疗医院。外科（下肢静脉曲张、痔疮、乳腺等）、内科（胃·大肠内镜、健康体检）、骨科（疼痛·关节·脊柱非手术治疗）多科协作诊疗。', description_ja = '整形外科・内科・外科の複合診療クリニック。外科（下肢静脈瘤、痔、乳腺など）、内科（胃・大腸内視鏡、健康診断）、整形外科（痛み・関節・脊椎の非手術治療）による協力診療。', business_hours_en = 'Mon-Fri 09:00-17:00 (lunch break 13:00-14:00) / Sat 09:00-13:00 / Closed Sun (closed 08/15 Liberation Day, 08/17 substitute holiday)', business_hours_zh = '周一至周五 09:00-17:00（午休13:00-14:00）/ 周六 09:00-13:00 / 周日休诊（8月15日光复节、8月17日替代假日休息）', business_hours_ja = '月~金 09:00-17:00（昼休み13:00-14:00）/ 土 09:00-13:00 / 日休診（8/15光復節、8/17振替休日休診）' WHERE reg_no = '13';
UPDATE hospital SET description_en = 'A plastic surgery clinic in Haeundae. Services include eye surgery (double eyelid, upper/lower blepharoplasty, revision), rhinoplasty, breast surgery, youthful-look procedures (forehead lift), lifting (thread lift, Shurink, Ulthera, Thermage), fillers, Botox, and skin boosters.', description_zh = '海云台整形外科。诊疗项目包括眼部整形（双眼皮·上下眼睑·修复手术）、鼻部整形、胸部整形、抗衰老整形（额部提升）、提升（线雕·Shurink·Ulthera·Thermage）、玻尿酸填充·肉毒素·水光针等。', description_ja = '海雲台の美容外科。目の整形（二重・上下眼瞼・再手術）、鼻の整形、豊胸、若返り整形（額リフト）、リフティング（糸リフト・シュリンク・ウルセラ・サーマジ）、フィラー・ボトックス・スキンブースターなどを診療。', business_hours_en = 'Mon/Tue/Wed/Fri 09:30-18:30 (lunch break 13:00-14:00, last check-in 18:00) / Thu 14:00-20:00 (last check-in 19:30) / Sat 10:00-15:00 (last check-in 14:30) / Closed Sun (closed 08/15 Liberation Day, 08/17 substitute holiday)', business_hours_zh = '周一·周二·周三·周五 09:30-18:30（午休13:00-14:00，最晚挂号18:00）/ 周四 14:00-20:00（最晚挂号19:30）/ 周六 10:00-15:00（最晚挂号14:30）/ 周日休诊（8月15日光复节、8月17日替代假日休息）', business_hours_ja = '月・火・水・金 09:30-18:30（昼休み13:00-14:00、受付終了18:00）/ 木 14:00-20:00（受付終了19:30）/ 土 10:00-15:00（受付終了14:30）/ 日休診（8/15光復節、8/17振替休日休診）' WHERE reg_no = '14';
UPDATE hospital SET description_en = 'Specializes in non-surgical Korean-medicine treatment for spinal disc conditions. Founded on the medical philosophy of compassion. Departments: Korean rehabilitation medicine, acupuncture, Korean internal medicine, Korean gynecology, Korean ENT/dermatology, and radiology. Main conditions treated: herniated spinal/lumbar discs, spinal stenosis, cervical disc herniation and forward head posture, TMJ disorder, and degenerative joint/spine disease. Treatments: Chuna manual therapy, motion-style acupuncture, Shinbaro herbal medicine/acupuncture, and manual therapy. Korea''s most-chosen Korean-medicine hospital for spine patients (2.3 million patients as of 2022).', description_zh = '专注韩医非手术脊柱椎间盘治疗。创院理念：矜恤之心的医疗哲学。诊疗科室：韩方康复医学科、针灸科、韩方内科、韩方妇科、韩方耳鼻喉皮肤科、影像医学科。主要疾病：脊柱椎间盘·腰椎间盘突出·椎管狭窄症，颈椎间盘突出·颈椎生理曲度变直，颞下颌关节紊乱，关节脊柱退行性疾病等。治疗方法：推拿疗法、动态针法、新八味韩药/药针、徒手治疗等。韩国脊柱患者选择最多的韩医院（截至2022年累计230万人）。', description_ja = '韓方による非手術脊椎椎間板治療専門。設立理念：矜恤之心（きょうじゅつのこころ）の医療哲学。診療科目：韓方リハビリテーション医学科、鍼灸科、韓方内科、韓方婦人科、韓方耳鼻咽喉皮膚科、画像医学科。主な疾患：脊椎椎間板・腰椎椎間板ヘルニア・脊柱管狭窄症、頸椎椎間板ヘルニア・ストレートネック、顎関節症、関節脊椎の退行性疾患など。治療法：推拿療法、動作鍼、シンバロ韓方薬/薬鍼、徒手治療など。国内で最も多くの脊椎患者に選ばれた韓方病院（2022年基準230万人）。', business_hours_en = 'Mon-Fri 09:00-20:00 / Sat 09:00-18:00 (lunch break 13:00-14:00, last check-in 12:00) / Closed Sun (last treatment: weekdays 18:30, Sat/holidays 17:00)', business_hours_zh = '周一至周五 09:00-20:00 / 周六 09:00-18:00（午休13:00-14:00，最晚挂号12:00）/ 周日休诊（诊疗结束：工作日18:30，周六·假日17:00）', business_hours_ja = '月~金 09:00-20:00 / 土 09:00-18:00（昼休み13:00-14:00、受付終了12:00）/ 日休診（診療終了：平日18:30、土・祝日17:00）' WHERE reg_no = '15';
UPDATE hospital SET description_en = 'Samsung Rehan Women''s Clinic, an OB/GYN clinic in Haeundae. 1:1 personalized care from director Dr. Park Ju-young, an OB/GYN specialist trained at Samsung Seoul Hospital. Services include female genital surgery (labiaplasty, vaginal tightening surgery, etc.), vaginal tightening procedures, Brazilian laser hair removal, skin/weight clinics, gynecological exams and screenings (cervical cancer, vaginitis, pregnancy ultrasound, etc.), and menopause hormone therapy. Evening hours until 8pm every Tuesday and Thursday.', description_zh = '海云台妇产科三星丽韩女性医院。由三星首尔医院出身的妇产科专科朴珠英院长提供一对一定制诊疗。项目包括女性整形（小阴唇·大阴唇手术、阴道紧缩术等）、女性紧致护理、桑拿式激光脱毛、皮肤/减肥门诊、妇科诊疗·体检（宫颈癌、阴道炎、孕期超声等）、更年期激素治疗等。每周二·周四夜间诊疗至晚上8点。', description_ja = '海雲台産婦人科サムスンリハン女性クリニック。サムスンソウル病院出身の産婦人科専門医パク・ジュヨン代表院長による1対1オーダーメイド診療。女性整形（小陰唇・大陰唇手術、膣縮小術など）、女性タイトニング施術、ブラジリアンレーザー脱毛、皮膚/肥満クリニック、婦人科診療・検診（子宮頸がん、腟炎、妊娠超音波など）、更年期ホルモン治療など。毎週火・木曜は夜8時まで夜間診療。', business_hours_en = 'Mon/Wed/Fri 09:30-18:30 (last check-in 18:00) / Tue/Thu 09:30-20:00 (last check-in 19:30) / Sat 09:30-13:30 (last check-in 13:00) (lunch break 13:00-14:00) / Closed Sun (closed 08/15-16, 08/17 substitute holiday)', business_hours_zh = '周一·周三·周五 09:30-18:30（最晚挂号18:00）/ 周二·周四 09:30-20:00（最晚挂号19:30）/ 周六 09:30-13:30（最晚挂号13:00，午休13:00-14:00）/ 周日休诊（8月15~16日、8月17日替代假日休息）', business_hours_ja = '月・水・金 09:30-18:30（受付終了18:00）/ 火・木 09:30-20:00（受付終了19:30）/ 土 09:30-13:30（受付終了13:00、昼休み13:00-14:00）/ 日休診（8/15~16、8/17振替休日休診）' WHERE reg_no = '16';
UPDATE hospital SET description_en = 'Focuses on trauma suture care with evening hours until 10pm. Also treats cosmetic/reconstructive conditions (ptosis, entropion, deviated septum — covered by insurance where eligible), facial fractures (nasal/orbital/jaw), skin tumors, lifting, fat grafting, and scar laser treatment. Has inpatient rooms, an on-site anesthesiologist, and CT/X-ray equipment. Same-day reservations are not available for reconstructive (trauma) care.', description_zh = '以外伤缝合为主的夜间诊疗（至晚上10点）。同时诊疗整形重建项目（上睑下垂、睑内翻、鼻中隔偏曲等可使用医保手术）、面部骨折（鼻部·眼眶·上下颌骨折）、皮肤肿瘤、提升、脂肪移植、疤痕激光等。设有住院病房、常驻麻醉专科医生、配备CT/X光设备。重建诊疗（外伤）不接受当日预约。', description_ja = '外傷縫合を中心とした夜間診療（夜10時まで）を実施。美容再建（眼瞼下垂、眼瞼内反、鼻中隔弯曲症など保険手術可）、顔面骨折（鼻・眼窩・上下顎骨折）、皮膚腫瘍、リフティング、脂肪注入、瘢痕レーザーなども診療。入院室・麻酔専門医常駐・CT/X線完備。再建診療（外傷）は当日予約不可。', business_hours_en = 'Outpatient care 09:00-22:00 (lunch 12:30-13:30 or 17:00-18:00, varies by day) / Trauma care 09:00-22:00, open 365 days a year (check the website for exact hours)', business_hours_zh = '门诊诊疗 09:00-22:00（午休12:30-13:30或17:00-18:00，视星期而定）/ 外伤诊疗 全年365天 09:00-22:00 无休（具体时间请以官网为准）', business_hours_ja = '外来診療 09:00-22:00（昼休み12:30-13:30または17:00-18:00、曜日により異なる）/ 外傷診療 365日09:00-22:00年中無休（正確な時間は公式サイトでご確認ください）' WHERE reg_no = '17';
UPDATE hospital SET description_en = 'An anti-aging clinic based on stem cell and regenerative medicine (a Ministry of Health and Welfare-designated advanced regenerative medicine institution). Services include skin anti-aging (PRP, BMAC, SVF, and fat grafting), a hair loss clinic (growth factors, PRP, stem cells), non-surgical joint regeneration treatment, and anti-aging IV therapy.', description_zh = '以干细胞·再生医学为基础的抗衰老专科医院（保健福祉部指定尖端再生医疗实施机构）。诊疗项目包括皮肤抗衰老（PRP·BMAC·SVF及脂肪移植）、脱发门诊（生长因子·PRP·干细胞）、非手术关节再生治疗、抗衰老静脉注射等。', description_ja = '幹細胞・再生医学に基づくアンチエイジング専門クリニック（保健福祉部指定先端再生医療実施機関）。皮膚アンチエイジング（PRP・BMAC・SVFおよび脂肪注入）、薄毛クリニック（成長因子・PRP・幹細胞）、非手術関節再生治療、アンチエイジング静脈施術などを診療。', business_hours_en = 'Mon/Fri 10:00-19:00 / Tue/Thu 10:00-21:00 (evening hours, lunch break 13:00-14:00) / Closed Wed/Sun / Sat 09:00-13:00 (closed 08/15 Liberation Day)', business_hours_zh = '周一·周五 10:00-19:00 / 周二·周四 10:00-21:00（夜间诊疗，午休13:00-14:00）/ 周三·周日休诊 / 周六 09:00-13:00（8月15日光复节休息）', business_hours_ja = '月・金 10:00-19:00 / 火・木 10:00-21:00（夜間診療、昼休み13:00-14:00）/ 水・日休診 / 土 09:00-13:00（8/15光復節休診）' WHERE reg_no = '18';
UPDATE hospital SET description_en = 'Designated as a veterans-affiliated hospital by the Ministry of Patriots and Veterans Affairs, a Military Manpower Administration honor facility, a Ministry of Health and Welfare-registered institution for attracting foreign patients, and a partner institution of Busan Veterans Hospital. Provides precise, clinically validated diagnosis and surgery using advanced medical equipment.', description_zh = '获国家报勋处指定为报勋委托医院，兵务厅指定为兵役名门世家优待机构，保健福祉部指定为外国患者接诊机构，并为釜山报勋医院合作医疗机构。运用尖端医疗设备，提供经临床验证的精密诊断与手术。', description_ja = '国家報勲部指定の報勲委託病院、兵務庁指定の兵役名門家優待施設、保健福祉部指定の外国人患者誘致機関、釜山報勲病院の協力医療機関。先端医療機器と臨床検証を経た精密な診断・手術を提供。', business_hours_en = 'Mon/Tue/Thu/Fri 09:00-18:00 (lunch break 13:00-14:30) / Wed 09:00-13:00 / Sat 09:00-14:00 / Closed Sun', business_hours_zh = '周一·周二·周四·周五 09:00-18:00（午休13:00-14:30）/ 周三 09:00-13:00 / 周六 09:00-14:00 / 周日休诊', business_hours_ja = '月・火・木・金 09:00-18:00（昼休み13:00-14:30）/ 水 09:00-13:00 / 土 09:00-14:00 / 日休診' WHERE reg_no = '19';
UPDATE hospital SET description_en = '5th floor: OB/GYN / women''s health clinic / female cosmetic surgery clinic / pregnancy termination / breast & thyroid surgery / uterine fibroid HIFU clinic / health checkup center / skin care clinic / hair loss clinic / body management clinic. 4th floor: operating rooms / procedure rooms / inpatient rooms. MediWoman Women''s Clinic has served Haeundae for 20 years. Director Dr. Baek Dong-hun, an OB/GYN specialist with 25 years of experience, offers non-surgical HIFU treatment for uterine fibroids/adenomyosis; Dr. Lee Hong-ju runs breast/thyroid and skin clinic care.', description_zh = '5楼：妇产科/女性疾病门诊/女性整形门诊/终止妊娠/乳腺甲状腺外科/子宫肌瘤海扶刀门诊/健康体检中心/皮肤护理门诊/脱发门诊/体形管理门诊。4楼：手术室/处置室/住院病房。扎根海云台20年的Mediwoman女性医院。25年经验妇产科专科白东勋院长，提供子宫肌瘤/子宫腺肌症非手术海扶刀治疗，李洪珠院长负责乳腺/甲状腺及皮肤门诊运营。', description_ja = '5階：婦人科／女性疾患クリニック／女性整形クリニック／妊娠中絶／乳腺甲状腺外科／子宮筋腫HIFUクリニック／健康診断センター／皮膚管理クリニック／薄毛クリニック／体型管理クリニック。4階：手術室／処置室／入院室。海雲台で20年続くメディウーマン女性クリニック。産婦人科専門医歴25年のペク・ドンフン代表院長、子宮筋腫／子宮腺筋症の非手術HIFU施術、乳腺／甲状腺担当のイ・ホンジュ院長、皮膚クリニックを運営。', business_hours_en = 'Mon-Fri 09:00-18:00 (break 13:00-14:00, last check-in 17:30) / Sat 09:00-13:00 (last check-in 12:30) / Closed every Sunday, closed 08/15 Liberation Day', business_hours_zh = '周一至周五 09:00-18:00（休息13:00-14:00，最晚挂号17:30）/ 周六 09:00-13:00（最晚挂号12:30）/ 每周日定期休息，8月15日光复节休息', business_hours_ja = '月~金 09:00-18:00（休憩13:00-14:00、受付終了17:30）/ 土 09:00-13:00（受付終了12:30）/ 毎週日曜定休、8/15光復節休診' WHERE reg_no = '20';
UPDATE hospital SET description_en = 'Led by director Dr. Kang Min-chul. Located in Haeundae Centum. A dermatology specialist and former university professor. Centum''s largest disease treatment center, hyperbaric oxygen therapy available, with a separately run cosmetic center.', description_zh = '姜民哲代表院长坐诊。位于海云台Centum。皮肤科专科医生，大学教授出身。Centum地区规模最大的疾病诊疗中心，可进行高压氧治疗，美容中心独立运营。', description_ja = 'カン・ミンチョル代表院長。海雲台センタム所在。大学教授出身の皮膚科専門医。センタム最大規模の疾患センター、高圧酸素治療対応、美容センターを分離運営。', business_hours_en = 'Mon 10:00-20:00 (lunch 13:00-14:30) / Tue-Fri same / Sat 10:00-15:00 / Closed Sun, closed 08/15 Liberation Day, 08/17 substitute holiday', business_hours_zh = '周一 10:00-20:00（午休13:00-14:30）/ 周二至周五 同上 / 周六 10:00-15:00 / 周日休诊，8月15日光复节、8月17日替代假日休息', business_hours_ja = '月 10:00-20:00（昼休み13:00-14:30）/ 火~金 同上 / 土 10:00-15:00 / 日休診、8/15光復節、8/17振替休日休診' WHERE reg_no = '21';
UPDATE hospital SET description_en = 'At Green Korean Medicine Clinic you can experience traditional moxibustion (basket moxa/long moxa). Diagnosis and prescriptions are also available based on Sasang constitutional medicine (per the Donguisusebowon).', description_zh = '来到绿色韩医院，可体验传统韩方艾灸（篓灸/长灸）。可依据四象体质进行诊断及处方（参考《东医寿世保元》）。', description_ja = 'グリーン韓医院では伝統韓方のもぐさ灸（かご灸/長灸）を体験できます。四象体質に基づく診断・処方も可能（東医寿世保元に基づく）。', business_hours_en = 'Mon-Fri 09:00-19:00 (lunch 13:00-14:00, last check-in 18:00) / Sat 09:00-13:00 / Closed Sun', business_hours_zh = '周一至周五 09:00-19:00（午休13:00-14:00，最晚挂号18:00）/ 周六 09:00-13:00 / 周日休诊', business_hours_ja = '月~金 09:00-19:00（昼休み13:00-14:00、受付終了18:00）/ 土 09:00-13:00 / 日休診' WHERE reg_no = '22';
UPDATE hospital SET description_en = 'Consultations begin on the 4th floor of Dangol Hospital starting July 3, 2026. Child development center attached on the 1st floor.', description_zh = '自2026年7月3日起，在단골医院4楼开始诊疗。1楼附设儿童发展中心。', description_ja = '2026年7月3日よりタンゴル病院4階で診療を開始します。1階に附設児童発達センターあり。', business_hours_en = 'Mon/Tue/Thu/Fri 09:00-23:00 (lunch 12:30-14:00) / Closed Wed / Sat/Sun 09:00-18:00', business_hours_zh = '周一·周二·周四·周五 09:00-23:00（午休12:30-14:00）/ 周三休诊 / 周六·周日 09:00-18:00', business_hours_ja = '月・火・木・金 09:00-23:00（昼休み12:30-14:00）/ 水休診 / 土・日 09:00-18:00' WHERE reg_no = '23';
UPDATE hospital SET description_en = 'Goodwill Dental in Busan Seomyeon. 28 years of experience. Implants performed by a doctor of dental science, and orthodontics led by an Invisalign clinical advisory dentist. A designated national oral checkup institution and a leading institution for attracting foreign patients.', description_zh = '釜山西面古德威尔牙科。28年经验。由牙医学博士主刀种植牙，隐适美临床顾问医生负责牙齿矫正。国家口腔体检机构，外国患者接诊先导医疗机构。', description_ja = '釜山ソミョンのグッドウィル歯科。28年の経験。歯学博士が執刀するインプラント、インビザライン臨床顧問医が担当する歯列矯正。国家口腔検診機関、外国人患者誘致先導医療機関。', business_hours_en = 'Mon/Tue/Thu 09:30-21:00 / Wed/Fri 09:30-18:30 / Sat 09:30-17:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一·周二·周四 09:30-21:00 / 周三·周五 09:30-18:30 / 周六 09:30-17:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月・火・木 09:30-21:00 / 水・金 09:30-18:30 / 土 09:30-17:00 / 日休診、8/15光復節休診' WHERE reg_no = '24';
UPDATE hospital SET description_en = 'The Face Plastic Surgery Clinic at Seomyeon Station Exit 7 in Busan. Eyes / nose / lifting / mid-life procedures / revision surgery / laser / minor procedures. Performs only truly necessary surgery based on precise examination and diagnosis, with 1:1 care.', description_zh = '釜山西面站7号出口더페이스（The Face）整形外科医院。眼部/鼻部/提升/中年整形/修复手术/激光/微整形。基于精密检查与诊断，只进行确有必要的手术，一对一贴心护理。', description_ja = '釜山ソミョン駅7番出口ザ・フェイス美容外科クリニック。目/鼻/リフティング/ミドルエイジ向け/再手術/レーザー/プチ整形。精密検査と診断に基づき本当に必要な手術のみ実施、1対1ケア。', business_hours_en = 'Mon-Fri 10:00-19:00 (lunch 13:00-14:00) / Sat 10:00-17:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周五 10:00-19:00（午休13:00-14:00）/ 周六 10:00-17:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~金 10:00-19:00（昼休み13:00-14:00）/ 土 10:00-17:00 / 日休診、8/15光復節休診' WHERE reg_no = '25';
UPDATE hospital SET description_en = 'Noblesse Dermatology, 8F Noblesse Tower, Seomyeon Station Exit 7. Opened in 2015, led by dermatology specialist Dr. Choi Gyu-won. A certified institution for scar/pigmentation/vascular disorder treatment.', description_zh = '西面站7号出口Noblesse大厦8楼Noblesse皮肤科。2015年开院，皮肤科专科崔圭元院长坐诊。疤痕/色素/血管疾病治疗认证机构。', description_ja = 'ソミョン駅7番出口ノブレスタワー8F ノブレス皮膚科。2015年開院、皮膚科専門医チェ・ギュウォン院長。瘢痕/色素/血管疾患治療認証機関。', business_hours_en = 'Tue-Fri 09:30-19:00 (lunch 12:30-14:00) / Sat 09:00-15:00 / Closed Mon/Sun, closed 08/15 Liberation Day', business_hours_zh = '周二至周五 09:30-19:00（午休12:30-14:00）/ 周六 09:00-15:00 / 周一·周日休诊，8月15日光复节休息', business_hours_ja = '火~金 09:30-19:00（昼休み12:30-14:00）/ 土 09:00-15:00 / 月・日休診、8/15光復節休診' WHERE reg_no = '26';
UPDATE hospital SET description_en = 'Focused on breast and rhinoplasty surgery, plus eye surgery, lifting, fillers, Botox, and laser. Plastic surgery specialist trained at Yonsei University Severance Hospital. No ghost surgery — live CCTV viewing of the operating room is available.', description_zh = '以胸部整形、鼻部整形为主，兼顾眼部整形、提升、玻尿酸填充、肉毒素、激光。延世大学世福兰斯医院出身的整形外科专科医生。杜绝代做手术，可实时观看手术室CCTV直播。', description_ja = '豊胸、鼻整形を中心に、目の整形、リフティング、フィラー、ボトックス、レーザーも実施。延世大学セブランス病院出身の美容外科専門医。代理手術なし、手術室のLIVE CCTV閲覧可能。', business_hours_en = 'Mon-Thu 10:00-19:00 / Fri 10:00-20:00 / Sat 10:00-17:00 / Closed Sun, closed 08/15, 08/17', business_hours_zh = '周一至周四 10:00-19:00 / 周五 10:00-20:00 / 周六 10:00-17:00 / 周日休诊，8月15日、8月17日休息', business_hours_ja = '月~木 10:00-19:00 / 金 10:00-20:00 / 土 10:00-17:00 / 日休診、8/15、8/17休診' WHERE reg_no = '27';
UPDATE hospital SET description_en = '2nd floor across from Haeundae Station Exits 1 and 3. Procedures performed directly by a dermatology specialist: hair transplant, under-eye fat repositioning, lifting/elasticity treatment, pigmentation, and scar treatment.', description_zh = '海云台站1、3号出口对面2楼。皮肤科专科医生亲自操作，植发、眼下脂肪重置、提升/紧致、色素、疤痕治疗。', description_ja = '海雲台駅1・3番出口前2階。皮膚科専門医が直接施術、毛髪移植、目の下の脂肪再配置、リフティング/弾力ケア、色素、瘢痕治療。', business_hours_en = 'Mon/Tue/Thu 10:00-19:00 / Wed 14:00-19:00 / Fri 10:00-20:30 / Sat 09:30-13:30 / Closed Sun, closed 08/15, 08/17', business_hours_zh = '周一·周二·周四 10:00-19:00 / 周三 14:00-19:00 / 周五 10:00-20:30 / 周六 09:30-13:30 / 周日休诊，8月15日、8月17日休息', business_hours_ja = '月・火・木 10:00-19:00 / 水 14:00-19:00 / 金 10:00-20:30 / 土 09:30-13:30 / 日休診、8/15、8/17休診' WHERE reg_no = '28';
UPDATE hospital SET description_en = 'HK Korea Korean Medicine Clinic. Combines advanced diagnostic and treatment systems with traditional Korean medicine. One-stop checkup system, in-house herbal pharmacy for medicine management, and appointment-based operation.', description_zh = 'HK韩国韩医院。融合尖端检测·治疗系统与传统韩医。设一站式体检系统、院内煎药室管理韩药，实行预约制。', description_ja = 'HK韓国韓医院。先端の検査・治療システムと伝統韓方を融合。ワンストップ検診システム、院内煎じ室での韓方薬管理、予約制運営。', business_hours_en = 'Mon-Wed 09:00-18:00 / Thu 13:00-20:00 / Fri/Sat closed every other week / Closed Sun, closed 08/10, 08/15', business_hours_zh = '周一至周三 09:00-18:00 / 周四 13:00-20:00 / 周五·周六隔周休诊 / 周日休诊，8月10日、8月15日休息', business_hours_ja = '月~水 09:00-18:00 / 木 13:00-20:00 / 金・土隔週休診 / 日休診、8/10、8/15休診' WHERE reg_no = '29';
UPDATE hospital SET description_en = 'Located in Seomyeon, Busan. Eye surgery (student double eyelid, mid-life double eyelid, revision eye surgery), rhinoplasty (revision), fat grafting, thread lifting, facelift surgery, and InMode lifting. Based on 1:1 specialist consultation.', description_zh = '位于釜山西面。眼部整形（学生双眼皮、中年双眼皮、眼部修复手术）、鼻部整形（修复手术）、脂肪移植、线雕提升、面部提升术、InMode提升。以专科医生一对一咨询为基础。', description_ja = '釜山ソミョン所在。目の整形（学生向け二重、ミドル世代の二重、目の再手術）、鼻整形（再手術）、脂肪注入、糸リフティング、フェイスリフト、インモードリフティング。専門医による1対1カウンセリングが基本。', business_hours_en = 'Mon-Fri 10:00-19:00 / Sat 10:00-17:00 / Closed Sun, closed 08/15, 08/17', business_hours_zh = '周一至周五 10:00-19:00 / 周六 10:00-17:00 / 周日休诊，8月15日、8月17日休息', business_hours_ja = '月~金 10:00-19:00 / 土 10:00-17:00 / 日休診、8/15、8/17休診' WHERE reg_no = '30';
