UPDATE hospital SET description_en = 'New patients can book by phone or Naver Reservation, returning patients by phone. Foreign patients can book via English chat on Kakao or an English Naver Reservation.', description_zh = '初诊患者可通过电话/Naver预约，复诊患者电话预约，外国患者可通过Kakao英文聊天/Naver英文预约。', description_ja = '新患は電話/NAVER予約、再診患者は電話予約、外国人患者はKakao英語チャット/NAVER英語予約が可能。', business_hours_en = 'Mon 09:00-18:00 / Tue-Fri 09:00-17:00 (lunch 12:30-13:30) / Sat 09:00-13:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一 09:00-18:00 / 周二至周五 09:00-17:00（午休12:30-13:30）/ 周六 09:00-13:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月 09:00-18:00 / 火~金 09:00-17:00（昼休み12:30-13:30）/ 土 09:00-13:00 / 日休診、8/15光復節休診' WHERE reg_no = '53';
UPDATE hospital SET description_en = 'Glory Women''s Clinic in Seomyeon. Gynecological screenings, pregnancy-related care, and female cosmetic surgery (vaginal laxity treatment, vaginal tightening procedures, labiaplasty, etc.).', description_zh = '西面Glory女性医院。妇科疾病体检、孕期相关诊疗、女性整形（阴道松弛治疗、阴道紧缩术、小阴唇手术等）。', description_ja = 'ソミョン グローリー女性クリニック。婦人科検診、妊娠関連診療、女性整形（腟弛緩症治療、腟タイトニング施術、小陰唇手術など）。', business_hours_en = 'Tue/Wed/Fri 09:30-18:30 / Closed Thu / Sat 09:30-15:30 / Closed Sun', business_hours_zh = '周二·周三·周五 09:30-18:30 / 周四休诊 / 周六 09:30-15:30 / 周日休诊', business_hours_ja = '火・水・金 09:30-18:30 / 木休診 / 土 09:30-15:30 / 日休診' WHERE reg_no = '54';
UPDATE hospital SET description_en = 'A Korean-medicine hospital near Yeonsan Station combining Western and Korean medicine. Features an 825m² manual therapy/rehabilitation/body correction center, a comprehensive health checkup center, and 98 inpatient beds. Open 365 days a year.', description_zh = '位于延山站附近的中西医结合韩医院。设有约825平方米的徒手治疗·康复·体形矫正中心、综合健康体检中心、98张住院病床。全年365天无休诊疗。', description_ja = 'ヨンサン駅近くの医科・韓方科統合韓方病院。約825平米規模の徒手治療・リハビリ・体型矯正センター、総合健康診断センター、98床の入院室。365日年中無休診療。', business_hours_en = 'Korean medicine daily 09:00-20:30 (Sat/Sun 09:00-16:00); internal medicine/orthopedics hours vary by day (admissions accepted 365 days a year)', business_hours_zh = '韩医科每日 09:00-20:30（周六·周日 09:00-16:00），内科·骨科诊疗时间视星期而定（全年365天可办理入院）', business_hours_ja = '韓方科は毎日09:00-20:30（土・日09:00-16:00）、内科・整形外科は曜日により異なる（365日入院手続き可能）' WHERE reg_no = '55';
UPDATE hospital SET description_en = '10 seconds on foot from Seomyeon Station Exits 5/7 (Lines 1, 2). Part of the Banobagi brand since 2000. Uses only genuine, correctly dosed products, and single-use cannulas/needles.', description_zh = '地铁1、2号线西面站5、7号出口步行10秒。自2000年起隶属Banobagi品牌。使用正品正量，采用一次性钝针·针头。', description_ja = '1・2号線ソミョン駅5・7番出口徒歩10秒。Since 2000、バノバギブランド。正規品・正量使用、使い捨てカニューレ・ニードル使用。', business_hours_en = 'Mon-Fri 10:00-20:00 / Sat 10:00-16:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周五 10:00-20:00 / 周六 10:00-16:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~金 10:00-20:00 / 土 10:00-16:00 / 日休診、8/15光復節休診' WHERE reg_no = '56';
UPDATE hospital SET description_en = 'Focused on hair transplant, tattoo removal, manual therapy, and skin aesthetics. Hair Transplant Center, Manual Therapy Center, and Skin Aesthetics Center (PicoWay, Tensherma/Shurink/InMode, etc.).', description_zh = '以植发、纹身去除、徒手治疗、皮肤美容为重点。设植发中心、徒手治疗中心、皮肤美容中心（蜂鸟、Tensherma·Shurink·InMode等）。', description_ja = '毛髪移植、タトゥー除去、徒手治療、皮膚美容が中心。毛髪移植センター、徒手治療センター、皮膚美容センター（ピコウェイ、テンサーマ・シュリンク・インモードなど）。', business_hours_en = 'Mon/Tue/Thu/Fri 10:00-21:00 / Closed Wed / Sat 10:00-17:00 / Closed Sun', business_hours_zh = '周一·周二·周四·周五 10:00-21:00 / 周三休诊 / 周六 10:00-17:00 / 周日休诊', business_hours_ja = '月・火・木・金 10:00-21:00 / 水休診 / 土 10:00-17:00 / 日休診' WHERE reg_no = '57';
UPDATE hospital SET description_en = 'Herbal medicine personally prepared by a Korean-medicine doctor with 20 years of clinical experience, combined with diet/lifestyle correction. Medicine is prepared in-house, aiming for fundamental treatment through metabolic recovery.', description_zh = '由拥有20年临床经验的韩医师亲自配制韩药，并结合饮食/生活习惯纠正。院内直接配药，致力于恢复代谢功能的根本治疗。', description_ja = '臨床経験20年の韓医師が自ら調剤する韓方薬 + 食事/生活習慣の改善。院内で直接調剤し、代謝機能回復による根本治療を目指します。', business_hours_en = 'Mon-Wed/Fri 10:00-19:00 / Closed Thu / Sat 10:00-14:00 / Closed Sun, closed 08/15, 08/17', business_hours_zh = '周一至周三·周五 10:00-19:00 / 周四休诊 / 周六 10:00-14:00 / 周日休诊，8月15日、8月17日休息', business_hours_ja = '月~水・金 10:00-19:00 / 木休診 / 土 10:00-14:00 / 日休診、8/15、8/17休診' WHERE reg_no = '58';
UPDATE hospital SET description_en = 'Located in Yeonsan-dong, Busan. Introduced university-hospital-grade equipment in 2014. A dental hospital with a system for screening, collaborative care, and follow-up management.', description_zh = '位于釜山延山洞。2014年引进大学医院级设备。设有体检·协作诊疗·术后管理体系的牙科医院。', description_ja = '釜山ヨンサン洞所在。2014年に大学病院級機器を導入。検診・協力診療・アフターケア体制を備えた歯科病院。', business_hours_en = 'Mon-Wed 09:30-21:00 / Thu/Fri 09:30-19:00 / Sat 09:30-15:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周三 09:30-21:00 / 周四·周五 09:30-19:00 / 周六 09:30-15:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~水 09:30-21:00 / 木・金 09:30-19:00 / 土 09:30-15:00 / 日休診、8/15光復節休診' WHERE reg_no = '59';
UPDATE hospital SET description_en = 'Seomyeon Station Exit 2. Korean medicine x Western medicine collaborative care. Chuna manual therapy/herbal prescriptions/acupuncture, manual and physical therapy, shockwave therapy. Treats traffic accident and workers'' compensation insurance cases, rehabilitation, and Korean internal medicine/pediatrics/gynecology.', description_zh = '西面站2号出口。韩医学 x 西医协作诊疗。推拿疗法/韩药处方/药针、徒手·物理治疗、体外冲击波。交通事故·工伤保险治疗、康复治疗、韩方内科·小儿科·妇科。', description_ja = 'ソミョン駅2番出口。韓医学×医学協力診療。推拿療法/韓方薬処方/薬鍼、徒手・物理治療、体外衝撃波。交通事故・労災保険治療、リハビリ治療、韓方内科・小児科・婦人科。', business_hours_en = 'Mon-Fri 09:30-21:00 / Sat 09:30-17:00 / Sun 10:00-17:00 (admissions accepted 365 days a year)', business_hours_zh = '周一至周五 09:30-21:00 / 周六 09:30-17:00 / 周日 10:00-17:00（全年365天可办理入院）', business_hours_ja = '月~金 09:30-21:00 / 土 09:30-17:00 / 日 10:00-17:00（365日入院手続き可能）' WHERE reg_no = '60';
UPDATE hospital SET description_en = 'Seomyeon''s only urban general hospital in Busan, connected to Buam Station Exit 6. VIP comprehensive checkup center and a designated emergency medical institution.', description_zh = '釜山西面唯一的都市型综合医院，与釜岩站6号出口相连。设VIP综合体检中心，急诊医疗机构。', description_ja = '釜山ソミョン唯一の都心型総合病院、プアム駅6番出口直結。VIP総合検診センター、救急医療機関。', business_hours_en = 'Mon 09:00-18:00 / Tue-Fri 09:00-17:00 / Sat 09:00-13:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一 09:00-18:00 / 周二至周五 09:00-17:00 / 周六 09:00-13:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月 09:00-18:00 / 火~金 09:00-17:00 / 土 09:00-13:00 / 日休診、8/15光復節休診' WHERE reg_no = '61';
UPDATE hospital SET description_en = 'Infertility treatment specialists offering IVF, artificial insemination, gynecological endoscopy, and more. Focused on emotional support and considerate, friendly service.', description_zh = '不孕不育治疗专业医疗团队，提供试管婴儿·人工授精·妇科内镜等诊疗。用心关怀，提供贴心友善的服务，助力身心稳定。', description_ja = '不妊治療分野の医療陣、体外受精・人工授精・婦人科内視鏡などを診療。心の安定に配慮した親切なサービス。', business_hours_en = 'Mon/Tue/Thu/Fri 09:00-19:00 / Wed 09:00-16:30 / Sat 09:00-12:30 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一·周二·周四·周五 09:00-19:00 / 周三 09:00-16:30 / 周六 09:00-12:30 / 周日休诊，8月15日光复节休息', business_hours_ja = '月・火・木・金 09:00-19:00 / 水 09:00-16:30 / 土 09:00-12:30 / 日休診、8/15光復節休診' WHERE reg_no = '62';
UPDATE hospital SET description_en = 'Appointment-based care. Career spanning Yonsei University, UCLA, Beverly Hills, and Seoul; opened in Dalmaji, Haeundae in October 2022. Holds both U.S. and Korean dental licenses, and care is available in English.', description_zh = '预约制诊疗。曾就职于延世大学-美国UCLA-比佛利山庄-首尔，2022年10月于海云台达迈开院。持有美国/韩国牙科执照，可提供英语诊疗。', description_ja = '予約制診療。延世大学-米国UCLA-ビバリーヒルズ-ソウルでのキャリア、2022年10月海雲台タルマジにオープン。米国/韓国の歯科免許保有、英語診療対応可能。', business_hours_en = 'Tue/Wed/Thu 10:00-17:00 / Closed Mon/Fri/Sat / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周二·周三·周四 10:00-17:00 / 周一·周五·周六休诊 / 周日休诊，8月15日光复节休息', business_hours_ja = '火・水・木 10:00-17:00 / 月・金・土休診 / 日休診、8/15光復節休診' WHERE reg_no = '63';
UPDATE hospital SET description_en = 'A designated Minish Members Clinic partner, with collaborative care from Ministry of Health and Welfare-certified specialists. Handles complex/revision implants (over 20,000 placements), with 3D CT and intraoral scanner digital diagnostics.', description_zh = '指定为Minish Members Clinic合作医院，保健福祉部认证专科医生协作诊疗，擅长高难度/修复种植牙（已完成超过2万例种植），配备3D-CT·口腔扫描仪数字化诊断。', description_ja = 'ミニッシュメンバーズクリニック指定病院、保健福祉部認証専門医による協力診療、高難度/再手術インプラント（2万件以上の実績）、3D-CT・口腔内スキャナーによるデジタル診断。', business_hours_en = 'Mon/Wed/Fri 10:00-19:00 / Tue/Thu 10:00-21:00 / Sat 10:00-16:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一·周三·周五 10:00-19:00 / 周二·周四 10:00-21:00 / 周六 10:00-16:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月・水・金 10:00-19:00 / 火・木 10:00-21:00 / 土 10:00-16:00 / 日休診、8/15光復節休診' WHERE reg_no = '64';
UPDATE hospital SET description_en = 'Lip fillers + mouth-corner Botox, facelift surgery, double eyelid + eye-shape correction + epicanthoplasty, fillers + thread lifting, nose tip surgery, Shurink, and Rejuran Healer. University-hospital-trained director on staff, specializing in revision surgery.', description_zh = '唇部填充+嘴角肉毒素、面部提升手术、双眼皮+眼型矫正+开眼角手术、玻尿酸填充+线雕提升、鼻尖整形、Shurink、丽珠兰Healer。大学医院出身院长常驻，专注修复手术。', description_ja = '唇フィラー+口角ボトックス、フェイスリフト手術、二重+目元矯正+目頭切開術、フィラー+糸リフティング、鼻先整形、シュリンク、リジュランヒーラー。大学病院出身の院長常駐、再手術専門。', business_hours_en = 'Mon/Tue/Wed/Fri 10:00-18:30 / Closed Thu / Sat 10:00-16:30 / Closed Sun, closed 08/15, 08/17', business_hours_zh = '周一·周二·周三·周五 10:00-18:30 / 周四休诊 / 周六 10:00-16:30 / 周日休诊，8月15日、8月17日休息', business_hours_ja = '月・火・水・金 10:00-18:30 / 木休診 / 土 10:00-16:30 / 日休診、8/15、8/17休診' WHERE reg_no = '65';
UPDATE hospital SET description_en = 'Gyeongin Korean Medicine Clinic''s Dr. Park Tae-yeol, a Korean medicine PhD with 38 years of clinical experience. Provides post-surgery bladder cancer recurrence management, chemotherapy side-effect management, and treatment for chronic cystitis and urinary incontinence. Prepares the Gongsindan herbal formula in-house.', description_zh = '京仁韩医院朴泰烈院长，临床38年韩医学博士。诊疗膀胱癌术后复发管理、抗癌后遗症管理、慢性膀胱炎、尿失禁等。院内亲自配制拱辰丹。', description_ja = 'キョンイン韓医院パク・テヨル院長、臨床38年の韓医学博士。膀胱がん手術後の再発管理、抗がん後遺症管理、慢性膀胱炎、尿失禁などを診療。コンシンダンを院内で直接調剤。', business_hours_en = 'Mon-Wed 09:30-18:30 (lunch 12:30-14:00) / Thu-Sat closed every other week / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周三 09:30-18:30（午休12:30-14:00）/ 周四至周六隔周休诊 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~水 09:30-18:30（昼休み12:30-14:00）/ 木~土隔週休診 / 日休診、8/15光復節休診' WHERE reg_no = '66';
UPDATE hospital SET description_en = 'A fertility-focused hospital, celebrating its 39th anniversary. Led by renowned fertility specialist Dr. Lee Sang-chan and 6 other fertility specialists. Offers artificial insemination, IVF, frozen embryo transfer, and runs a fertility preservation clinic.', description_zh = '专注不孕不育治疗的医院，开院39周年。不孕不育权威医生李相灿院长携6名不孕不育专科医疗团队。开展人工授精·试管婴儿·冷冻胚胎移植，并设生育力保存门诊。', description_ja = '不妊治療専門病院、開院39周年。不妊治療の名医イ・サンチャン院長ほか6名の不妊専門医療陣。人工授精・体外受精・凍結胚移植、妊孕性温存クリニックを運営。', business_hours_en = 'Mon-Fri 08:00-17:00 (lunch 13:00-14:00) / Sat 08:00-13:00 / Closed Sun (only pre-booked procedures on public holidays)', business_hours_zh = '周一至周五 08:00-17:00（午休13:00-14:00）/ 周六 08:00-13:00 / 周日休诊（法定假日仅进行已预约项目）', business_hours_ja = '月~金 08:00-17:00（昼休み13:00-14:00）/ 土 08:00-13:00 / 日休診（祝日は予約済み施術のみ実施）' WHERE reg_no = '67';
UPDATE hospital SET description_en = 'Located in Beomil-dong, Dong-gu, and the founding hospital of the 12-hospital Eunsung Medical Foundation Good Hospital network, opened in 1978. Provides early diagnosis through surgery for gynecological, breast, and thyroid cancer, using the 4th-generation da Vinci robotic surgery system. Operates a comprehensive health checkup center.', description_zh = '位于东区凡一洞，隶属恩星医疗财团旗下12家好医院的发源院，1978年开院。提供从早期诊断到手术的妇科癌·乳腺癌·甲状腺癌全流程诊疗，配备第四代达芬奇机器人手术系统。设综合健康体检中心。', description_ja = '東区ボミル洞所在、ウンソン医療財団傘下12のグッド病院の母体、1978年開院。婦人科がん・乳がん・甲状腺がんの早期診断から手術まで、第4世代ダヴィンチロボット手術システム。総合健康診断センターを運営。', business_hours_en = 'Mon 09:00-18:00 / Tue-Fri 09:00-17:00 / Sat 09:00-13:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一 09:00-18:00 / 周二至周五 09:00-17:00 / 周六 09:00-13:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月 09:00-18:00 / 火~金 09:00-17:00 / 土 09:00-13:00 / 日休診、8/15光復節休診' WHERE reg_no = '68';
UPDATE hospital SET description_en = 'Located in Namcheon-dong, Suyeong-gu, a general hospital under the Eunsung Medical Foundation. Emergency room operates 24 hours. Collaborative care across internal medicine, surgery, orthopedics, and neurology.', description_zh = '位于水营区南川洞，隶属恩星医疗财团的综合医院。急诊室24小时运营。内科·外科·骨科·神经内科等协作诊疗。', description_ja = '水営区ナムチョン洞所在、ウンソン医療財団傘下の総合病院。救急室24時間運営。内科・外科・整形外科・神経科など協力診療。', business_hours_en = 'Mon 09:00-18:00 / Tue-Fri 09:00-17:00 / Sat 09:00-13:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一 09:00-18:00 / 周二至周五 09:00-17:00 / 周六 09:00-13:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月 09:00-18:00 / 火~金 09:00-17:00 / 土 09:00-13:00 / 日休診、8/15光復節休診' WHERE reg_no = '69';
UPDATE hospital SET description_en = 'Dong-A University Hospital — always with you through compassion and medical excellence.', description_zh = '以仁爱与仁术始终陪伴您的东亚大学医院。', description_ja = '愛と仁術で常に共にある東亜大学校病院。', business_hours_en = 'Mon-Fri 08:00-17:00 / Closed Sat/Sun, closed 08/15, 08/17 (Emergency Medical Center open 24 hours, 365 days a year)', business_hours_zh = '周一至周五 08:00-17:00 / 周六·周日休诊，8月15日、8月17日休息（急诊医疗中心全年365天24小时开放）', business_hours_ja = '月~金 08:00-17:00 / 土・日休診、8/15、8/17休診（救急医療センターは365日24時間対応）' WHERE reg_no = '70';
UPDATE hospital SET description_en = 'A general hospital focused on joints, spine, and internal medicine. Includes a Joint Center, Spine Center, Cardio-Cerebrovascular Center, Rehabilitation Exercise Therapy Center, Trauma/Fracture Center, and Digestive Center. 385 beds total, with a 24-hour regional emergency medical facility.', description_zh = '以关节·脊柱·内科为中心的综合医院。设关节中心、脊柱中心、心脑血管中心、康复运动治疗中心、外伤骨折中心、消化科中心等。共385张病床，24小时运营地区急诊医疗机构。', description_ja = '関節・脊椎・内科中心の総合病院。関節センター、脊椎センター、心脳血管センター、リハビリ運動治療センター、外傷骨折センター、消化器センターなど。総病床数385床、地域救急医療機関として24時間運営。', business_hours_en = 'Mon 09:00-18:00 / Tue-Fri 09:00-17:00 / Sat 09:00-13:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一 09:00-18:00 / 周二至周五 09:00-17:00 / 周六 09:00-13:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月 09:00-18:00 / 火~金 09:00-17:00 / 土 09:00-13:00 / 日休診、8/15光復節休診' WHERE reg_no = '71';
UPDATE hospital SET description_en = 'Led by a director with 32 years of medical experience, with specialized care by field. A staff anesthesiology/pain medicine specialist with 34 years of experience.', description_zh = '代表院长拥有32年从医经验，按各领域细分诊疗。常驻34年经验的麻醉痛症医学科专科医生。', description_ja = '医師歴32年の代表院長、各分野ごとの専門診療。34年のキャリアを持つ麻酔痛症医学科専門医が常駐。', business_hours_en = 'Mon-Fri 10:00-19:00 / Sat 10:00-17:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周五 10:00-19:00 / 周六 10:00-17:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~金 10:00-19:00 / 土 10:00-17:00 / 日休診、8/15光復節休診' WHERE reg_no = '72';
UPDATE hospital SET description_en = 'Since 1997, with over 28 years of experience and more than 600,000 surgeries performed. Launched Bright World AI. Offers SMILE Pro/ZEISS SMILE/2-Day LASEK, ICL, laser multifocal cataract surgery, and Dream Lens (Ortho-K).', description_zh = '始于1997年，28年以上经验，累计手术超60万例。推出光明世界AI（밝은세상AI）。开展SMILE Pro/蔡司全飞秒/2日LASEK、ICL、激光多焦点白内障、梦戴维角膜塑形镜。', description_ja = 'SINCE1997、28年以上・60万件以上の手術実績。「バルグンセサンAI」を導入。スマイルプロ/ツァイススマイル/2デイラゼック、ICL、レーザー多焦点白内障、ドリームレンズ（オルソケラトロジー）。', business_hours_en = 'Mon/Tue/Thu/Fri 09:00-18:00 / Closed Wed / Sat 09:00-16:00 / Closed Sun, closed 08/17', business_hours_zh = '周一·周二·周四·周五 09:00-18:00 / 周三休诊 / 周六 09:00-16:00 / 周日休诊，8月17日休息', business_hours_ja = '月・火・木・金 09:00-18:00 / 水休診 / 土 09:00-16:00 / 日休診、8/17休診' WHERE reg_no = '73';
