UPDATE hospital SET description_en = 'Opened in 1951, a 75-year-old general hospital in Seo-gu, part of a global network of 180 medical institutions worldwide. Regular outpatient hours on Sundays, and a Ministry of Health and Welfare-certified medical institution.', description_zh = '1951年开院，拥有75年历史的西区综合医院，隶属全球180家医院组成的国际医疗网络。周日门诊正常诊疗，保健福祉部认证医疗机构。', description_ja = '1951年開院、75年の歴史を持つ西区の総合病院、世界180の病院からなるグローバル医療ネットワーク加盟。日曜も外来通常診療、保健福祉部認証医療機関。', business_hours_en = 'Mon-Thu 08:30-17:30 / Fri 08:30-12:30 / Closed Sat / Sun 08:30-17:30 (regular outpatient hours)', business_hours_zh = '周一至周四 08:30-17:30 / 周五 08:30-12:30 / 周六休诊 / 周日 08:30-17:30（门诊正常诊疗）', business_hours_ja = '月~木 08:30-17:30 / 金 08:30-12:30 / 土休診 / 日 08:30-17:30（外来通常診療）' WHERE reg_no = '75';
