UPDATE hospital SET description_en = 'Recognized as an institution with a low C-section rate. Named an institution with a high natural delivery rate for 5 consecutive years from 2004-2008. Over 1,200 laparoscopic surgeries performed.', description_zh = '获评低剖腹产率医疗机构。2004~2008年连续5年获评高自然分娩率医疗机构。腹腔镜手术超1200例。', description_ja = '帝王切開分娩率が低い医療機関に選定。2004～2008年5年連続で自然分娩率が高い医療機関。腹腔鏡手術1,200例以上。', business_hours_en = 'Mon-Fri 09:00-18:00 (lunch 13:00-14:00) / Sat 09:00-13:00 / Closed Sun, closed 08/15 Liberation Day (24-hour delivery/emergency maternity care)', business_hours_zh = '周一至周五 09:00-18:00（午休13:00-14:00）/ 周六 09:00-13:00 / 周日休诊，8月15日光复节休息（分娩·急诊产妇24小时应诊）', business_hours_ja = '月~金 09:00-18:00（昼休み13:00-14:00）/ 土 09:00-13:00 / 日休診、8/15光復節休診（分娩・救急妊産婦は24時間対応）' WHERE reg_no = '80';
UPDATE hospital SET description_en = 'Maria Hospital, a fertility specialist. Artificial insemination, IVF, recurrent miscarriage care, and a fertility preservation center. Ranked #1 in Busan for pregnancy success rate in 2016 (49.39%).', description_zh = '不孕不育专科玛丽亚医院。人工授精、试管婴儿、复发性自然流产、生育力保存中心。2016年怀孕成功率釜山第一（49.39%）。', description_ja = '不妊治療専門マリア病院。人工授精、体外受精、反復流産ケア、妊孕性温存センター。2016年妊娠成功率釜山第1位（49.39%）。', business_hours_en = 'Mon-Fri 07:30-16:30 (lunch 12:00-13:30) / Sat 07:30-12:30 / Closed Sun, closed 08/15, 08/17', business_hours_zh = '周一至周五 07:30-16:30（午休12:00-13:30）/ 周六 07:30-12:30 / 周日休诊，8月15日、8月17日休息', business_hours_ja = '月~金 07:30-16:30（昼休み12:00-13:30）/ 土 07:30-12:30 / 日休診、8/15、8/17休診' WHERE reg_no = '81';
UPDATE hospital SET description_en = 'Founded in 1951 as St. Benedict Hospital, with over 70 years of history. Certified by the Ministry of Health and Welfare for 4 consecutive terms. Rated Grade A as a regional emergency medical institution for 3 consecutive years.', description_zh = '1951年以圣本笃医院起步，70余年历史。连续4次通过保健福祉部医疗机构认证。作为地区急诊医疗机构连续3年获评A级。', description_ja = '1951年に聖ベネディクト病院として開院、70年を超える歴史。保健福祉部医療機関認証を4回連続取得。地域救急医療機関として3年連続A等級。', business_hours_en = 'Mon-Fri 08:30-17:30 (lunch 12:30-13:30) / Sat 08:30-12:30 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周五 08:30-17:30（午休12:30-13:30）/ 周六 08:30-12:30 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~金 08:30-17:30（昼休み12:30-13:30）/ 土 08:30-12:30 / 日休診、8/15光復節休診' WHERE reg_no = '82';
UPDATE hospital SET description_en = 'Provides care in thyroid, diabetes, nephrology, gastroenterology, a comprehensive health checkup center, general surgery, family medicine, radiology, pathology, neurology, and occupational and environmental medicine.', description_zh = '诊疗甲状腺、糖尿病、肾内科、消化内科、综合健康体检中心、普外科、家庭医学科、影像医学科、病理科、神经内科、职业环境医学科。', description_ja = '甲状腺、糖尿病、腎臓内科、消化器内科、総合健康診断センター、一般外科、家庭医学科、画像医学科、病理科、神経科、産業環境医学科を診療。', business_hours_en = 'Mon-Thu 08:00-18:00 / Fri 08:00-17:30 / Sat 08:00-13:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周四 08:00-18:00 / 周五 08:00-17:30 / 周六 08:00-13:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~木 08:00-18:00 / 金 08:00-17:30 / 土 08:00-13:00 / 日休診、8/15光復節休診' WHERE reg_no = '83';
UPDATE hospital SET description_en = 'Centum Precious Eye Clinic. Vision correction surgery (SMILE/LASIK/LASEK/ICL), cataract/presbyopia, eye disease care (dry eye, glaucoma, macular degeneration, diabetic retinopathy), and Dream Lens (Ortho-K).', description_zh = 'Centum珍贵之眼眼科。视力矫正手术（全飞秒/LASIK/LASEK/ICL）、白内障/老花、眼病（干眼症/青光眼/黄斑变性/糖尿病视网膜病变）、梦戴维角膜塑形镜。', description_ja = 'センタム大切な目の眼科。視力矯正手術（スマイル/レーシック/ラゼック/ICL）、白内障/老眼、眼疾患（ドライアイ/緑内障/黄斑変性/糖尿病網膜症）、ドリームレンズ。', business_hours_en = 'Mon-Thu 09:00-18:30 / Fri 09:00-19:00 / Sat 09:00-14:00 / Closed Sun, closed 08/15, 08/17', business_hours_zh = '周一至周四 09:00-18:30 / 周五 09:00-19:00 / 周六 09:00-14:00 / 周日休诊，8月15日、8月17日休息', business_hours_ja = '月~木 09:00-18:30 / 金 09:00-19:00 / 土 09:00-14:00 / 日休診、8/15、8/17休診' WHERE reg_no = '84';
UPDATE hospital SET description_en = '22 years as a Busan varicose vein specialty institution. Director Dr. Kim Byeong-jun, a cardiovascular thoracic surgery specialist with 28 years of experience. 12F Yeonggwang Bookstore, Seomyeon Station Exit 9.', description_zh = '22年釜山下肢静脉曲张专科医疗机构。28年经验心脏血管胸外科专科金炳俊院长坐诊。西面站9号出口永光书店12楼。', description_ja = '22年間釜山下肢静脈瘤専門医療機関。28年のキャリアを持つ心臓血管胸部外科専門医キム・ビョンジュン院長。ソミョン駅9番出口ヨングァン書店12階。', business_hours_en = 'Mon/Tue/Thu/Fri/Sat 09:00-18:00 / Closed Wed / Closed Sun, closed 08/15, 08/17', business_hours_zh = '周一·周二·周四·周五·周六 09:00-18:00 / 周三休诊 / 周日休诊，8月15日、8月17日休息', business_hours_ja = '月・火・木・金・土 09:00-18:00 / 水休診 / 日休診、8/15、8/17休診' WHERE reg_no = '85';
UPDATE hospital SET description_en = 'A public institution under the Ministry of Science and ICT. Conducts advanced biomedical research and provides medical services including specialized cancer care and health checkups.', description_zh = '隶属科学技术信息通信部的公共机构。开展尖端医学生命研究，提供专业化癌症诊疗、健康体检等医疗服务。', description_ja = '科学技術情報通信部傘下の公共機関。先端医生命研究を実施し、特化されたがん診療、健康診断など医療サービスを提供。', business_hours_en = 'Mon-Fri 09:00-17:30 (lunch 12:30-13:30) / Closed Sat/Sun (Emergency Room open 24 hours, every day)', business_hours_zh = '周一至周五 09:00-17:30（午休12:30-13:30）/ 周六·周日休诊（急诊室00:00-24:00全年无休）', business_hours_ja = '月~金 09:00-17:30（昼休み12:30-13:30）/ 土・日休診（救急室00:00-24:00年中無休）' WHERE reg_no = '86';
UPDATE hospital SET description_en = 'Next to the Busan Lotte Hotel. Dedicated care centers on each floor of Nune Medi Tower, 7F-13F. SMILE/SMILE Pro/LASIK/LASEK/lens implantation, and presbyopia/cataract/retinal disease care. 6 ophthalmology specialists.', description_zh = '紧邻釜山乐天酒店。누네Medi大厦7-13楼各设专科诊疗中心。开展全飞秒/SMILE Pro/LASIK/LASEK/晶体植入术，诊疗老花·白内障·视网膜疾病。6名眼科专科医生。', description_ja = '釜山ロッテホテル隣。ヌネメディタワー7-13階に各フロア別診療センター。スマイル/スマイルプロ/レーシック/ラゼック/眼内レンズ挿入術、老眼・白内障・網膜疾患。眼科専門医6名。', business_hours_en = 'Mon/Tue/Thu/Fri 09:00-19:00 / Wed 09:00-18:00 / Sat 08:30-14:00 / Closed Sun', business_hours_zh = '周一·周二·周四·周五 09:00-19:00 / 周三 09:00-18:00 / 周六 08:30-14:00 / 周日休诊', business_hours_ja = '月・火・木・金 09:00-19:00 / 水 09:00-18:00 / 土 08:30-14:00 / 日休診' WHERE reg_no = '87';
UPDATE hospital SET description_en = 'Opened as Park Hee-du Surgery Clinic in 1986, became Busan Seongso Clinic in 1991, and rebuilt with 205 beds in 2012. Focuses on thyroid conditions, orthopedics, and health checkups.', description_zh = '1986年以朴熙斗外科医院开院，1991年更名为釜山圣召医院，2012年新建205张病床。以甲状腺疾病·骨科·健康体检为重点。', description_ja = '1986年パク・ヒドゥ外科医院として開院、1991年釜山ソンソ医院、2012年205床規模で新築。甲状腺疾患・整形外科・健康診断が中心。', business_hours_en = 'Mon-Fri 09:00-17:30 (lunch 13:00-14:00) / Sat 09:00-13:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周五 09:00-17:30（午休13:00-14:00）/ 周六 09:00-13:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~金 09:00-17:30（昼休み13:00-14:00）/ 土 09:00-13:00 / 日休診、8/15光復節休診' WHERE reg_no = '88';
UPDATE hospital SET description_en = 'The only joint specialty hospital in the western Busan area. Reached 100,000 orthopedic surgeries as of November 2025. Designated as a joint specialty hospital by the Ministry of Health and Welfare.', description_zh = '西釜山地区唯一关节专科医院。截至2025年11月骨科手术量达10万例。保健福祉部指定关节专科医院。', description_ja = '西釜山圏唯一の関節専門病院。2025年11月時点で整形外科手術件数100,000例達成。保健福祉部指定関節専門病院。', business_hours_en = 'Mon-Fri 09:00-20:00 (lunch 13:00-14:00) / Sat/Sun 09:00-13:00 (24-hour orthopedic night care available)', business_hours_zh = '周一至周五 09:00-20:00（午休13:00-14:00）/ 周六·周日 09:00-13:00（骨科24小时夜间诊疗）', business_hours_ja = '月~金 09:00-20:00（昼休み13:00-14:00）/ 土・日 09:00-13:00（整形外科24時間夜間診療）' WHERE reg_no = '89';
UPDATE hospital SET description_en = 'Director Son Hee-dong. Departments: eye surgery, rhinoplasty, functional rhinoplasty, lifting, facelift, revision surgery, breast surgery, male cosmetic surgery, gynecomastia, minor procedures, and skin care.', description_zh = '代表院长孙熙东。诊疗项目：眼部整形、鼻部整形、功能性鼻整形、提升、面部提升、修复手术、胸部整形、男性整形、男性乳房发育症、微整形、皮肤护理。', description_ja = '代表院長ソン・ヒドン。診療科目：目の整形、鼻整形、機能的鼻整形、リフティング、フェイスリフト、再手術、豊胸、メンズ整形、女性化乳房、プチ施術、スキンケア。', business_hours_en = 'Mon-Fri 10:00-19:00 / Sat 10:00-17:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周五 10:00-19:00 / 周六 10:00-17:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~金 10:00-19:00 / 土 10:00-17:00 / 日休診、8/15光復節休診' WHERE reg_no = '90';
UPDATE hospital SET description_en = 'Director Dr. Baek Tae-min, with 33 years of experience. Over 140,000 comprehensive eye surgeries performed. Presbyopia/Cataract Center, pediatric ophthalmology, vision correction, glaucoma, and eyelid/eye surgery.', description_zh = '33年经验白泰民代表院长坐诊。综合眼部手术量超14万例。老花白内障中心、小儿眼科、视力矫正、青光眼、眼部整形。', description_ja = '33年のキャリアを持つペク・テミン代表院長。眼科総合手術実績14万件以上。老眼白内障センター、小児眼科、視力矯正、緑内障、眼形成。', business_hours_en = 'Mon-Fri 09:30-18:00 (lunch 13:00-14:00) / Sat 09:30-13:00 / Closed Sun, closed 08/17', business_hours_zh = '周一至周五 09:30-18:00（午休13:00-14:00）/ 周六 09:30-13:00 / 周日休诊，8月17日休息', business_hours_ja = '月~金 09:30-18:00（昼休み13:00-14:00）/ 土 09:30-13:00 / 日休診、8/17休診' WHERE reg_no = '91';
UPDATE hospital SET description_en = 'Opened in 1963, and pioneered the country''s first orthopedic-focused hospital model in 1983. Combines core orthopedics with internal medicine, rehabilitation medicine, and a manual therapy center. Operates a 24-hour emergency room.', description_zh = '1963年开院，1983年领跑全国首创骨科重点医院模式。以骨科为核心，兼设内科、康复医学科、徒手治疗中心。24小时急诊室运营。', description_ja = '1963年開院、1983年全国初の整形外科中心病院を先導。整形外科を基本に内科、リハビリテーション医学科、徒手治療センターを併設。24時間救急室運営。', business_hours_en = 'Mon-Fri 09:00-18:00 (lunch 12:30-13:30) / Sat 09:00-13:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周五 09:00-18:00（午休12:30-13:30）/ 周六 09:00-13:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~金 09:00-18:00（昼休み12:30-13:30）/ 土 09:00-13:00 / 日休診、8/15光復節休診' WHERE reg_no = '92';
UPDATE hospital SET description_en = 'Located at BS Medical Center in Busan Seomyeon. Director Dr. Jeong Seong-hun (plastic surgery specialist / MD, PhD).', description_zh = '位于釜山西面BS Medical Center。郑成勋院长（整形外科专科医生/医学博士）坐诊。', description_ja = '釜山ソミョンBSメディカルセンター所在。チョン・ソンフン院長（美容外科専門医/医学博士）。', business_hours_en = 'Mon/Tue/Wed/Fri 10:00-18:00 / Thu 10:00-12:00 / Sat 10:00-16:00 / Closed Sun, closed 08/15, 08/17', business_hours_zh = '周一·周二·周三·周五 10:00-18:00 / 周四 10:00-12:00 / 周六 10:00-16:00 / 周日休诊，8月15日、8月17日休息', business_hours_ja = '月・火・水・金 10:00-18:00 / 木 10:00-12:00 / 土 10:00-16:00 / 日休診、8/15、8/17休診' WHERE reg_no = '93';
UPDATE hospital SET description_en = 'Focused on endoscopic breast surgery. Early breast cancer diagnosis, with breast-conserving and reconstruction surgery via endoscopy. 6F Elium Building, in front of Jangsan Station Exit 11.', description_zh = '专注内镜乳腺手术。乳腺癌早期诊断，通过内镜手术进行保乳·重建。长山站11号出口对面Elium大厦6楼。', description_ja = '内視鏡乳房手術に特化。乳がん早期診断、内視鏡手術による温存・再建。チャンサン駅11番出口前エリウムビル6階。', business_hours_en = 'Mon-Fri 08:30-17:30 (lunch 12:30-13:30) / Sat 08:30-13:30 / Closed Sun, closed 08/15, 08/17', business_hours_zh = '周一至周五 08:30-17:30（午休12:30-13:30）/ 周六 08:30-13:30 / 周日休诊，8月15日、8月17日休息', business_hours_ja = '月~金 08:30-17:30（昼休み12:30-13:30）/ 土 08:30-13:30 / 日休診、8/15、8/17休診' WHERE reg_no = '94';
UPDATE hospital SET description_en = 'Located at Seomyeon Station. Staff from well-known Gangnam plastic surgery clinics. Breast surgery, double-jaw surgery, facial contouring, eye/nose revision surgery plus orbital decompression, burn treatment, rhinitis surgery, and breast reconstruction.', description_zh = '位于西面站。医疗团队出身江南知名整形外科。胸部整形、双颌手术、面部轮廓、眼鼻修复手术+眼眶减压术、烧伤治疗、鼻炎手术、乳房重建。', description_ja = 'ソミョン駅所在。江南の有名美容外科出身の医療陣。豊胸、両顎手術、顔輪郭、目・鼻の再手術+眼窩減圧術、熱傷治療、鼻炎手術、乳房再建。', business_hours_en = 'Mon-Fri 10:00-19:00 / Sat 10:00-17:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周五 10:00-19:00 / 周六 10:00-17:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~金 10:00-19:00 / 土 10:00-17:00 / 日休診、8/15光復節休診' WHERE reg_no = '95';
UPDATE hospital SET description_en = 'Opened in 1945, with 20 departments and 10 specialty centers. Over 700 staff and around 100 doctors. Founded the Daedong University nursing department, and serves as a medical training hub for Busan.', description_zh = '1945年开院，设20个诊疗科·10个专业中心。700余名员工、约100名医生。设立大同大学护理学系，是釜山市医疗培训枢纽。', description_ja = '1945年開院、20の診療科・10の専門センター。700名以上のスタッフ、100名前後の医師。テドン大学看護学科を設立、釜山市の医療研修拠点。', business_hours_en = 'Mon-Fri 09:00-17:00 (lunch 12:30-13:30) / Sat 09:00-12:00 / Closed Sun', business_hours_zh = '周一至周五 09:00-17:00（午休12:30-13:30）/ 周六 09:00-12:00 / 周日休诊', business_hours_ja = '月~金 09:00-17:00（昼休み12:30-13:30）/ 土 09:00-12:00 / 日休診' WHERE reg_no = '96';
UPDATE hospital SET description_en = 'Suyeong Station Exit 2, 12 years at the same location. First visits include intraoral photos and a precision diagnostic consultation.', description_zh = '水营站2号出口，在同一地址已诊疗12年。首次就诊将进行口内拍照及精密诊断咨询。', description_ja = '水営駅2番出口、同じ場所で12年診療。初診時に口腔内写真撮影と精密診断カウンセリングを実施。', business_hours_en = 'Mon/Wed 09:30-18:30 / Tue 09:30-20:30 / Thu 14:00-20:30 / Closed Fri/Sat / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一·周三 09:30-18:30 / 周二 09:30-20:30 / 周四 14:00-20:30 / 周五·周六休诊 / 周日休诊，8月15日光复节休息', business_hours_ja = '月・水 09:30-18:30 / 火 09:30-20:30 / 木 14:00-20:30 / 金・土休診 / 日休診、8/15光復節休診' WHERE reg_no = '97';
UPDATE hospital SET description_en = 'Specialist medical staff with extensive clinical experience, equipped with advanced medical equipment and emergency preparedness gear. An anesthesiology specialist is on staff.', description_zh = '拥有丰富临床经验的专科医疗团队，配备尖端专业医疗设备及应急处置设备。常驻麻醉科专科医生。', description_ja = '多様な臨床経験を持つ専門医療陣、先端専門医療機器および緊急対応機器を完備。麻酔科専門医常駐。', business_hours_en = 'Mon-Fri 09:00-19:00 / Sat 09:00-17:00 / Closed Sun', business_hours_zh = '周一至周五 09:00-19:00 / 周六 09:00-17:00 / 周日休诊', business_hours_ja = '月~金 09:00-19:00 / 土 09:00-17:00 / 日休診' WHERE reg_no = '98';
UPDATE hospital SET description_en = 'Director Dr. Lim Ju-hwan, a plastic surgery specialist from Seoul National University with 19 years of experience. Eye surgery, mid-life eye surgery, foreign material removal, youthful-look procedures, facial fat surgery, and minor procedures. Operates a surgical outcome guarantee program.', description_zh = '首尔大学出身，19年经验整形外科专科林周焕代表院长坐诊。眼部整形、中年眼部整形、异物取出、抗衰老整形、面部脂肪整形、微整形。实行手术结果责任保障制。', description_ja = 'ソウル大学出身、19年のキャリアを持つ美容外科専門医イム・ジュファン代表院長。目の整形、ミドル世代の目の整形、異物除去、若返り整形、顔の脂肪整形、プチ整形。手術結果責任保証制を実施。', business_hours_en = 'Closed Mon-Wed / Thu/Fri 10:00-19:00 / Sat 10:00-16:00 / Closed Sun, closed 08/12, 08/15, 08/17, 08/19', business_hours_zh = '周一至周三休诊 / 周四·周五 10:00-19:00 / 周六 10:00-16:00 / 周日休诊，8月12日、8月15日、8月17日、8月19日休息', business_hours_ja = '月~水休診 / 木・金 10:00-19:00 / 土 10:00-16:00 / 日休診、8/12、8/15、8/17、8/19休診' WHERE reg_no = '99';
UPDATE hospital SET description_en = 'Dental care balancing function and aesthetics. Clear aligner orthodontics (precision scanning equipment), prosthodontics/implants (domestically and internationally certified premium lines), and a philosophy of no unnecessary overtreatment.', description_zh = '兼顾功能与美观的牙科治疗。透明矫正（精密扫描设备）、修复/种植牙（国内外认证高端产品线），秉持杜绝不必要过度诊疗的理念。', description_ja = '機能と審美性のバランスが取れた歯科治療。マウスピース矯正（精密スキャン機器）、補綴/インプラント（国内外認証のプレミアムラインナップ）、不要な過剰診療を行わない診療哲学。', business_hours_en = 'Mon/Tue/Thu/Fri 09:30-18:30 / Wed 09:30-21:00 / Sat 09:30-14:00 / Closed Sun, closed 08/15, 08/17', business_hours_zh = '周一·周二·周四·周五 09:30-18:30 / 周三 09:30-21:00 / 周六 09:30-14:00 / 周日休诊，8月15日、8月17日休息', business_hours_ja = '月・火・木・金 09:30-18:30 / 水 09:30-21:00 / 土 09:30-14:00 / 日休診、8/15、8/17休診' WHERE reg_no = '100';
UPDATE hospital SET description_en = 'Reservations guided by phone. Open on Saturdays and Sundays too. Opened as a dental hospital in 1994.', description_zh = '预约请通过电话咨询。周六、周日均照常诊疗。1994年以牙科医院开院。', description_ja = '予約はお電話でご案内。土曜・日曜も診療。1994年歯科病院として開院。', business_hours_en = 'Mon/Tue/Wed/Fri 09:00-18:00 / Closed Thu / Sat/Sun 09:00-14:00', business_hours_zh = '周一·周二·周三·周五 09:00-18:00 / 周四休诊 / 周六·周日 09:00-14:00', business_hours_ja = '月・火・水・金 09:00-18:00 / 木休診 / 土・日 09:00-14:00' WHERE reg_no = '101';
UPDATE hospital SET description_en = 'Located in Busan Seomyeon, occupying B1F-8F entirely as an ophthalmology hospital. A certified hospital with 100,000 SMILE LASIK procedures. An official ZEISS certified center. 9 ophthalmology specialists, with a retina specialist on staff.', description_zh = '位于釜山西面，地下1楼至地上8楼全层均为眼科医院。SMILE全飞秒手术量达10万眼认证医院。蔡司官方认证中心。9名眼科专科医生，常驻视网膜专科医生。', description_ja = '釜山ソミョン所在、B1F-8F全フロアが眼科病院。スマイルレーシック100,000眼達成認証病院。ZEISS公式認証センター。眼科専門医9名、網膜専門医常駐。', business_hours_en = 'Mon-Fri 09:00-18:00 (lunch 13:00-14:00) / Sat 09:00-17:00 / Closed Sun (only the Presbyopia/Cataract Center operates on Wednesdays)', business_hours_zh = '周一至周五 09:00-18:00（午休13:00-14:00）/ 周六 09:00-17:00 / 周日休诊（周三仅运营老花白内障中心）', business_hours_ja = '月~金 09:00-18:00（昼休み13:00-14:00）/ 土 09:00-17:00 / 日休診（水曜は老眼白内障センターのみ運営）' WHERE reg_no = '102';
UPDATE hospital SET description_en = 'Western and Korean medicine collaborative care since 1990. Capable of treating neurological conditions such as cerebrovascular disease and facial paralysis, as well as musculoskeletal conditions involving the spine and joints.', description_zh = '自1990年起开展西医·韩医协作诊疗。具备诊疗脑血管疾病·面瘫等神经系统疾病，以及脊柱关节疾病等肌肉系统疾病的能力。', description_ja = '1990年から西洋医学・韓方の協力診療。脳血管疾患・顔面麻痺など神経系疾患、脊椎関節疾患など筋肉系疾患の診療力を保有。', business_hours_en = 'Mon-Fri 08:30-17:30 / Sat 08:30-12:30 / Closed Sun, closed 08/15 Liberation Day (weekend/holiday hours 09:00-17:00)', business_hours_zh = '周一至周五 08:30-17:30 / 周六 08:30-12:30 / 周日休诊，8月15日光复节休息（周末·法定假日09:00-17:00）', business_hours_ja = '月~金 08:30-17:30 / 土 08:30-12:30 / 日休診、8/15光復節休診（週末・祝日は09:00-17:00）' WHERE reg_no = '103';
