UPDATE hospital SET description_en = 'Founded in 1952 by an Australian medical missionary as a tent clinic in Seo-gu, Busan. Offers OB/GYN, pediatrics, internal medicine, surgery, and many other departments. Operates a Neonatal Intensive Care Unit (NICU) and a comprehensive health promotion center.', description_zh = '1952年由澳大利亚医疗传教士在釜山西区以帐篷诊所起步。设妇产科·小儿科·内科·外科等多个诊疗科。运营新生儿重症监护室（NICU）、综合健康促进中心。', description_ja = '1952年オーストラリア人医療宣教師が釜山西区にテント診療所として開設。産婦人科・小児科・内科・外科など多数の診療科。新生児集中治療室（NICU）、総合健康増進センターを運営。', business_hours_en = 'Mon-Fri 08:30-17:30 (lunch 12:30-13:30) / Sat 08:30-12:30 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周五 08:30-17:30（午休12:30-13:30）/ 周六 08:30-12:30 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~金 08:30-17:30（昼休み12:30-13:30）/ 土 08:30-12:30 / 日休診、8/15光復節休診' WHERE reg_no = '107';
UPDATE hospital SET description_en = 'Busan Vascular Surgery Hospital. Specialized care for venous disease, arterial disease, dialysis access, and women''s health (uterine fibroid embolization). University-hospital-grade diagnostic/treatment equipment, with a partnership network including Pusan National, Dong-A, and Inje University hospitals.', description_zh = '釜山血管外科医院。专注静脉疾病、动脉疾病、透析血管、女性疾病（子宫肌瘤栓塞术）诊疗。配备大学医院级诊断·治疗设备，与釜山大学·东亚大学·仁济大学建立协作体系。', description_ja = '釜山血管外科病院。静脈疾患、動脈疾患、透析血管、女性疾患（子宮筋腫塞栓術）に特化した診療。大学病院級の診断・治療機器、釜山大学・東亜大学・仁済大学との協力体制。', business_hours_en = 'Mon-Fri 09:00-18:00 (lunch 12:30-13:30) / Sat 09:00-13:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周五 09:00-18:00（午休12:30-13:30）/ 周六 09:00-13:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~金 09:00-18:00（昼休み12:30-13:30）/ 土 09:00-13:00 / 日休診、8/15光復節休診' WHERE reg_no = '108';
