UPDATE hospital SET description_en = 'Care by a general surgery specialist with a subspecialty in colorectal surgery. University-hospital-grade advanced laparoscopic surgery system, a pelvic floor disorder treatment center, emergency surgery availability, and an integrated cancer center.', description_zh = '普外科专科医生诊疗，大肠肛门外科细分专科。配备大学医院级尖端腹腔镜手术系统、盆底疾病治疗中心，可进行急诊手术，设综合癌症中心。', description_ja = '外科専門医による診療、大腸肛門外科細分専門医。大学病院級の先端腹腔鏡手術システム、骨盤底疾患治療センター、緊急手術対応可能、統合がんセンター。', business_hours_en = 'Mon 09:00-18:00 / Tue-Fri 09:00-17:00 (lunch 13:00-14:00) / Sat 09:00-13:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一 09:00-18:00 / 周二至周五 09:00-17:00（午休13:00-14:00）/ 周六 09:00-13:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月 09:00-18:00 / 火~金 09:00-17:00（昼休み13:00-14:00）/ 土 09:00-13:00 / 日休診、8/15光復節休診' WHERE reg_no = '110';
UPDATE hospital SET description_en = 'Specializes in presbyopia, cataract, LASIK, LASEK, and eyelid/eye surgery. Smart 5-Second LASIK and navigation-guided LASIK surgery. Located across from Seomyeon Lotte Department Store.', description_zh = '专注老花、白内障、LASIK、LASEK、眼部整形手术。Smart5秒LASIK、导航引导LASIK手术。位于西面乐天百货对面。', description_ja = '老眼、白内障、レーシック、ラゼック、眼形成手術専門。スマート5秒レーシック、ナビゲーションレーシック手術。ソミョンロッテ百貨店向かい所在。', business_hours_en = 'Mon-Fri 09:30-18:00 (lunch 13:00-14:00) / Sat 09:30-13:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周五 09:30-18:00（午休13:00-14:00）/ 周六 09:30-13:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~金 09:30-18:00（昼休み13:00-14:00）/ 土 09:30-13:00 / 日休診、8/15光復節休診' WHERE reg_no = '111';
