UPDATE hospital SET description_en = '1:1 personalized care with a single-surgeon responsibility system. No ghost surgery, with a sterilization system in place. Eye surgery, rhinoplasty, forehead lift, facelift, fat grafting/liposuction, breast surgery, and thread lifting.', description_zh = '一对一定制诊疗，主刀医生全程负责制。杜绝代做手术，配备灭菌消毒系统。眼部整形、鼻部整形、额部提升、面部提升、脂肪移植/吸脂、胸部整形、线雕提升。', description_ja = '1対1オーダーメイド診療、担当執刀医責任制。代理手術排除、滅菌消毒システム。目の整形、鼻整形、額リフト、フェイスリフト、脂肪注入/吸引、豊胸、糸リフティング。', business_hours_en = 'Mon-Fri 10:00-18:30 / Sat 09:30-15:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周五 10:00-18:30 / 周六 09:30-15:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~金 10:00-18:30 / 土 09:30-15:00 / 日休診、8/15光復節休診' WHERE reg_no = '113';
