UPDATE hospital SET description_en = 'A spine specialty hospital serving Busan, Ulsan, and Gyeongnam. Spine conditions (lower back/neck/upper back) and joint conditions (shoulder/elbow/wrist/hip/ankle/knee). Focused on root-cause treatment and minimally invasive procedures.', description_zh = '釜山、蔚山、庆南地区脊柱专科医院。脊柱疾病（腰部/颈部/背部）、关节疾病（肩/肘/腕/髋/踝/膝）。以病因治疗、微创手术为导向。', description_ja = '釜山・蔚山・慶南の脊椎専門病院。脊椎疾患（腰/首/背中）、関節疾患（肩/肘/手首/股関節/足首/膝）。原因治療、最小切開を志向。', business_hours_en = 'Mon-Fri 09:00-17:30 / Sat 09:00-13:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周五 09:00-17:30 / 周六 09:00-13:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~金 09:00-17:30 / 土 09:00-13:00 / 日休診、8/15光復節休診' WHERE reg_no = '118';
