UPDATE hospital SET description_en = 'A hospital specializing in disc treatment. Uses the latest diagnostic equipment, cutting-edge digital imaging surgery, and the MedX exercise therapy program. Prioritizes treatment without surgery whenever possible.', description_zh = '专注椎间盘治疗的医院。配备最新诊断设备、尖端数字影像手术系统、MedX运动治疗项目。以尽量不手术的保守治疗为优先。', description_ja = '椎間板治療特化病院。最新診断機器、最先端デジタル画像手術、メデックス運動治療プログラム。可能な限り手術せずに治療する方針。', business_hours_en = 'Mon-Fri 09:00-18:00 (lunch 12:30-13:30) / Sat 09:00-13:00 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周五 09:00-18:00（午休12:30-13:30）/ 周六 09:00-13:00 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~金 09:00-18:00（昼休み12:30-13:30）/ 土 09:00-13:00 / 日休診、8/15光復節休診' WHERE reg_no = '121';
UPDATE hospital SET description_en = 'Opened in 2000 in Nampo-dong, Jung-gu, Busan, a plastic surgery specialist institution. Main procedures are eye/facial wrinkle surgery, with an anti-aging specialty. Also offers a medical skin care program.', description_zh = '2000年于釜山中区南浦洞开院的整形外科专科医疗机构。以眼部·面部除皱手术为主，专注抗衰老。同时开展医学皮肤护理项目。', description_ja = '2000年釜山中区南浦洞に開院、美容外科専門医療機関。目元・顔のしわ取り手術が主要手術、アンチエイジング専門。医療スキンケアプログラムも併設。', business_hours_en = 'Mon-Fri 09:30-19:30 (lunch 12:00-13:00) / Sat 09:30-17:30 / Closed Sun, closed 08/15 Liberation Day', business_hours_zh = '周一至周五 09:30-19:30（午休12:00-13:00）/ 周六 09:30-17:30 / 周日休诊，8月15日光复节休息', business_hours_ja = '月~金 09:30-19:30（昼休み12:00-13:00）/ 土 09:30-17:30 / 日休診、8/15光復節休診' WHERE reg_no = '122';
